def dehydrate_point(value):
    """
    Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        # When there is no point to dehydrate, return None
        return None

    # If the value is already a basic iterable of coordinates, return it as a tuple
    if isinstance(value, (tuple, list)):
        if all(isinstance(coord, (int, float)) for coord in value):
            return tuple(value)
        # If it's some other iterable, just attempt to convert to a tuple
        try:
            return tuple(value)
        except Exception:
            pass

    # Handle Shapely-like Point objects: they expose .x, .y (and optionally .z)
    if hasattr(value, "x") and hasattr(value, "y"):
        coords = (value.x, value.y)
        if hasattr(value, "z") and value.z is not None:
            coords += (value.z,)
        return coords

    # Many geometric libraries provide a .coords or .xy attribute
    if hasattr(value, "coords"):
        try:
            return tuple(tuple(c) for c in value.coords)
        except Exception:
            pass
    if hasattr(value, "xy"):
        try:
            return tuple(zip(*value.xy))
        except Exception:
            pass

    # Some objects may provide a .tuple() method
    if hasattr(value, "tuple") and callable(value.tuple):
        try:
            return value.tuple()
        except Exception:
            pass

    # If it is an iterable of numeric values that didn't satisfy earlier checks
    if hasattr(value, "__iter__"):
        try:
            return tuple(value)
        except Exception:
            pass

    # If none of the above worked, raise an informative error
    raise TypeError(
        f"Unable to dehydrate point: unsupported type {type(value).__name__}"
    )

def dehydrate_point(value):
    """
    Dehydrator for Point data.

    Converts a geometry point to a standard string representation.

    :param value: a point-like object (shapely Point, Django GeoDjango Point, or simple object with .x/.y or .coords)
    :type value: Point
    :return: string representation of the point (WKT "POINT(lon lat)") or None if value is None
    :rtype: str | None
    """
    if value is None:
        return None

    # If the object has a WKT representation (common in GIS libraries)
    if hasattr(value, "wkt"):
        return value.wkt

    # Try to build a POINT string from x and y attributes
    if hasattr(value, "x") and hasattr(value, "y"):
        return f"POINT({value.x} {value.y})"

    # Fallback: try to extract coordinates from a tuple or list stored in .coords or attribute
    coords = None
    if hasattr(value, "coords"):
        coords = value.coords
    elif hasattr(value, "coordinate") or hasattr(value, "coordinate_tuple"):
        coords = getattr(value, "coordinate") or getattr(value, "coordinate_tuple")

    # Ensure coords is a tuple or list with at least two elements
    if coords is None:
        return None

    try:
        # shapely.Point.coords returns a coordinate sequence; take first element
        if isinstance(coords, (list, tuple)):
            # If it's a list of tuples (e.g., [(x, y)]), take first
            if isinstance(coords[0], (list, tuple)):
                x, y = coords[0]
            else:
                x, y = coords
        else:
            # Try to iterate
            it = iter(coords)
            x, y = next(it), next(it)
        return f"POINT({x} {y})"
    except Exception:
        # If anything goes wrong, return None
        return None

