def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Ensure the class has a mapping of handlers
        if not hasattr(cls, "_HANDLERS"):
            # If the mapping does not exist, create an empty dict
            # This can be overridden by subclasses
            cls._HANDLERS = {}

        # Validate the provided protocol_version
        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError(
                    f"protocol_version must be a tuple, not {type(protocol_version).__name__}"
                )
            if not all(isinstance(v, int) for v in protocol_version):
                raise TypeError(
                    "Each element in protocol_version tuple must be an int"
                )
            # Return either the single handler or an empty dict
            if protocol_version in cls._HANDLERS:
                return {protocol_version: cls._HANDLERS[protocol_version]}
            else:
                return {}

        # If no specific version asked for, return all handlers
        # We return a shallow copy to prevent accidental mutation.
        return dict(cls._HANDLERS)

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Validate protocol_version argument
        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError(
                    "protocol_version must be a tuple identifying the protocol version"
                )
            if len(protocol_version) != 2 or not all(
                isinstance(v, int) for v in protocol_version
            ):
                raise TypeError(
                    "protocol_version tuple must contain two integer values (major, minor)"
                )

        # Retrieve the full mapping of available handlers.  Subclass
        # implementations are expected to define a class attribute
        # `_protocol_handlers` that maps `(major, minor)` tuples to
        # handler classes.  Fall back gracefully if the attribute does
        # not exist.
        handlers_map = getattr(cls, "_protocol_handlers", {})

        # If no specific version is requested, return a copy of the
        # entire mapping.  If a version is requested, return a dict
        # containing only that entry (or an empty dict if unsupported).
        if protocol_version is None:
            return dict(handlers_map)
        if protocol_version in handlers_map:
            return {protocol_version: handlers_map[protocol_version]}
        return {}

def unit_of_work(metadata=None, timeout=None):
    """
    Decorator for transaction functions that adds optional metadata and a timeout.

    Supports both parameterized and non-parameterized usage:
    - @unit_of_work
    - @unit_of_work(metadata=..., timeout=...)
    """
    # ---------- Helper to apply the decorator ----------
    def _apply(func, meta, to):
        if not callable(func):
            raise TypeError("unit_of_work expects a callable as the decorated object")

        # Validate metadata
        if meta is not None and not isinstance(meta, dict):
            raise TypeError("metadata must be a dict or None")

        # Validate timeout
        if to is not None:
            if not isinstance(to, (int, float)):
                raise TypeError("timeout must be a number or None")
            if to < 0:
                raise ValueError("timeout must not be negative")

        # Wrapper simply forwards all arguments
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)

        # Attach the metadata and timeout as attributes for later use
        wrapper._unit_of_work_metadata = meta
        wrapper._unit_of_work_timeout = to
        return wrapper

    # ---------- Detect if used without parentheses ----------
    if callable(metadata) and timeout is None:
        # Usage: @unit_of_work
        return _apply(metadata, None, None)

    # Usage: @unit_of_work(...) or @unit_of_work(timeout=...)
    def decorator(func):
        return _apply(func, metadata, timeout)

    return decorator

