    # Locate the record's field names and values
    try:
        keys_list = getattr(self, 'keys')
    except AttributeError:
        try:
            keys_list = getattr(self, 'fields')
        except AttributeError:
            keys_list = getattr(self, '_keys', None)
    try:
        values_list = getattr(self, 'values')
    except AttributeError:
        try:
            values_list = getattr(self, 'items')
        except AttributeError:
            values_list = getattr(self, '_values', None)

    if keys_list is None or values_list is None:
        # Fallback: try to use __dict__ or other generic attributes
        keys_list = list(keys_list or getattr(self, '__slots__', []))
        values_list = [getattr(self, k, None) for k in keys_list]

    if not keys:
        return dict(zip(keys_list, values_list))

    # Map field names to indices for quick lookup
    name_to_index = {name: i for i, name in enumerate(keys_list)}

    result = {}
    for key in keys:
        if isinstance(key, int):
            idx = key
            if idx < 0:
                idx = len(values_list) + idx
            if idx < 0 or idx >= len(values_list):
                raise IndexError(f"Index {key} out of range")
            name = keys_list[idx]
            result[name] = values_list[idx]
        elif isinstance(key, str):
            if key in name_to_index:
                result[key] = values_list[name_to_index[key]]
            else:
                result[key] = None
        else:
            raise TypeError("Keys must be integers or strings")
    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
        """
        Appends a DISCARD message to the output queue.

        :param n: number of records to discard, default = -1 (ALL)
        :param qid: query ID to discard for, default = -1 (last query)
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        """
        # Build the DISCARD message
        message = {
            "method": "DISCARD",
            "params": {"n": n, "qid": qid}
        }

        # Apply dehydration hooks to params if provided
        if dehydration_hooks:
            for key, value in message["params"].items():
                typ = type(value)
                if typ in dehydration_hooks:
                    try:
                        message["params"][key] = dehydration_hooks[typ](value)
                    except Exception as exc:
                        raise ValueError(f"Dehydration hook for {typ} failed") from exc

        # Append the message to the output queue
        if not hasattr(self, "_output_queue"):
            self._output_queue = []
        self._output_queue.append(message)

        # Return a Response instance configured with the supplied hooks and handlers
        # The Response class is expected to exist on the instance
        if not hasattr(self, "Response"):
            raise AttributeError("The instance does not have a 'Response' attribute")

        return self.Response(
            hydration_hooks=hydration_hooks or {},
            **handlers
