        except TypeError:
            raise ValueError("bookmarks must be an iterable")
    if metadata:
        opts["metadata"] = metadata
    if timeout is not None:
        opts["timeout"] = timeout
    if db is not None:
        opts["db"] = db
    if imp_user is not None:
        opts["imp_user"] = imp_user
    # Send the BEGIN message to the server (using Bolt protocol)
    # 0x11 is the standard Bolt code for a BEGIN transaction
    self._write(0x11, opts)
