def _shuffled(seq: Sequence[str]) -> list[str]:
    data = list(seq)
    if not data:
        return []
    # Deterministic seed based on characters in the sequence
    seed = 0
    for s in data:
        for ch in s:
            seed = (seed * 31 + ord(ch)) & 0xFFFFFFFF
    n = len(data)
    # Fisher‑Yates shuffle using a simple LCG for pseudorandomness
    for i in range(n - 1, 0, -1):
        seed = (1103515245 * seed + 12345) & 0xFFFFFFFF
        j = seed % (i + 1)
        data[i], data[j] = data[j], data[i]
    return data

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    def _extract_int(part: str):
        i = 0
        n = len(part)
        sign = ''
        if i < n and (part[i] == '-' or part[i] == '+'):
            sign = part[i]
            i += 1
        start = i
        while i < n and part[i].isdigit():
            i += 1
        if start < i:
            try:
                return int(sign + part[start:i])
            except:
                pass
        return None

    nums = []
    for part in s.strip().split('.'):
        val = _extract_int(part)
        if val is not None:
            nums.append(val)
    return tuple(nums)

