def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """
    Normalise a command tuple so that Windows can execute it correctly.
    Works around Windows inability to parse shebang lines and the bug
    https://bugs.python.org/issue8557.
    """
    if not cmd:
        return cmd

    create, *args = cmd
    # Only attempt normalization on Windows when the executable name has
    # no recognised extension.
    if platform.system() == "Windows" and not os.path.splitext(create)[1]:
        try:
            with open(create, "rb") as f:
                line = f.readline().decode(errors="ignore")
            if line.startswith("#!"):
                # Strip the shebang and whitespace
                shebang = line[2:].strip()
                parts = shebang.split()
                if parts:
                    # Handle /usr/bin/env usage
                    if parts[0].endswith("env") or os.path.basename(parts[0]) == "env":
                        if len(parts) > 1:
                            interpreter = parts[1]
                        else:
                            interpreter = "env"
                    else:
                        interpreter = parts[0]

                    # Try to resolve the interpreter path
                    interp_path = shutil.which(interpreter)
                    if interp_path:
                        create = interp_path
                    else:
                        # If an absolute path was given, use it directly
                        if os.path.isabs(interpreter):
                            create = interpreter
        except Exception:
            pass

    return (create, *args)

