def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.
    """
    # Build graph of precedence constraints and acquire element rankings
    adj = {}
    indeg = {}
    rank = {} # (order_index, position)
    for oi, order in enumerate(orderings):
        for pos, x in enumerate(order):
            if x not in adj:
                adj[x] = set()
                indeg[x] = 0
            if x not in rank or (oi, pos) < rank[x]:
                rank[x] = (oi, pos)
        for a, b in zip(order, order[1:]):
            if b not in adj:  # ensure all nodes appear
                adj[b] = set()
                indeg[b] = 0
            if b not in adj[a]:
                adj[a].add(b)
                indeg[b] += 1

    # Kahn's algorithm with deterministic tie-breaking by rank
    from heapq import heappush, heappop
    heap = []
    for node, d in indeg.items():
        if d == 0:
            heappush(heap, (rank[node], node))
    result = []
    while heap:
        _, node = heappop(heap)
        result.append(node)
        for nb in adj[node]:
            indeg[nb] -= 1
            if indeg[nb] == 0:
                heappush(heap, (rank[nb], nb))
    # If we didn't include all nodes, there was a cycle; raise an error
    if len(result) != len(adj):
        raise ValueError("Cannot merge orderings due to cycle")
    return result

