def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments.

    Arguments can be individual interfaces, tuples, lists, or Declaration objects.
    Any iterable (except strings/bytes) will be expanded into the resulting list.
    """
    if output is None:
        output = []
    for arg in sequence:
        # If it's a non-string iterable, expand it
        if isinstance(arg, (list, tuple, set)):
            output.extend(arg)
        else:
            output.append(arg)
    return output

