def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value* or with *make_bins()*
    (depending on the initialization).
    """
    # Reset context if it exists.
    if hasattr(self, "context"):
        try:
            self.context.clear()
        except AttributeError:
            # If context is not a dict-like structure, reassign it to an empty dict
            self.context = {}
    elif hasattr(self, "_context"):
        try:
            self._context.clear()
        except AttributeError:
            self._context = {}

    # Reinitialize bins
    if hasattr(self, "initial_value"):
        """If an initial_value is provided, apply it to every existing bin."""
        # Ensure the bins structure exists
        bins = getattr(self, "bins", None) or getattr(self, "_bins", None)
        if bins is None:
            # If we have no bins yet, create an empty dict
            bins = {}
        # Apply the initial_value to each bin
        for key in bins:
            # If initial_value is a callable, call it to produce a new value per bin
            if callable(self.initial_value):
                bins[key] = self.initial_value()
            else:
                bins[key] = self.initial_value
        # Store the updated bins back
        if hasattr(self, "bins"):
            self.bins = bins
        else:
            self._bins = bins
    else:
        """Otherwise, reconstruct bins using the make_bins() method."""
        if hasattr(self, "make_bins"):
            new_bins = self.make_bins()
            if hasattr(self, "bins"):
                self.bins = new_bins
            else:
                self._bins = new_bins
        else:
            # No make_bins defined – fallback to an empty dictionary
            if hasattr(self, "bins"):
                self.bins = {}
            else:
                self._bins = {}

def to_csv(self, separator=",", header=None):
    lines = []
    if header is not None:
        lines.append(str(header))
    points = getattr(self, 'points', [])
    for point in points:
        coord, value = point
        if isinstance(coord, (list, tuple)):
            coord_parts = [str(c) for c in coord]
        else:
            coord_parts = [str(coord)]
        if isinstance(value, (list, tuple)):
            val_parts = [str(v) for v in value]
        else:
            val_parts = [str(value)]
        lines.append(separator.join(coord_parts + val_parts))
    return "\n".join(lines)

