def _get_err_indices(self, coord_name):
        """Get error indices corresponding to a coordinate."""
        err = None
        # Attempt to find error information in a dictionary named `_errors`
        if hasattr(self, "_errors"):
            try:
                err = self._errors[coord_name]
            except (KeyError, TypeError):
                err = None
        # Fall back to an attribute with suffix `_err`
        if err is None:
            try:
                err = getattr(self, coord_name + "_err")
            except AttributeError:
                err = None
        # If the coordinate object itself has an `err` attribute, use it
        if err is None:
            coord_obj = getattr(self, coord_name, None)
            if coord_obj is not None:
                err = getattr(coord_obj, "err", None)
        # If no error information is found, return None
        if err is None:
            return None
        # Convert list or tuple to a numpy array for consistent handling
        try:
            import numpy as np
        except ImportError:
            np = None
        # Handle list or tuple error containers
        if isinstance(err, (list, tuple)):
            # Return indices where the error element is not None and not zero
            return [
                i
                for i, val in enumerate(err)
                if val not in (None, 0, 0.0)
            ]
        # Handle numpy array if available
        if np is not None and isinstance(err, np.ndarray):
            return (
                np.where(
                    ~np.isnan(err)
                    & (~np.zeros_like(err, dtype=bool))
                    & (err != 0)
                )[0].tolist()
            )
        # Handle scalar error values
        try:
            if err not in (None, 0, 0.0):
                return [0]
        except Exception:
            pass
        return []

