def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Compute bin widths
    try:
        widths = edges[1:] - edges[:-1]
    except TypeError:
        widths = [edges[i+1] - edges[i] for i in range(len(edges)-1)]
    # Compute weighted sum
    return sum(b * w for b, w in zip(bins, widths))

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Validate input lengths
    if len(bins) == 0:
        return 0.0
    if len(edges) != len(bins) + 1:
        raise ValueError("edges must be one element longer than bins")
    # Compute area as sum of bin_value * bin_width
    return sum(v * (e1 - e0) for v, e0, e1 in zip(bins, edges, edges[1:]))

