    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Ensure coordinate is iterable and has correct dimensionality
    try:
        coord_iter = tuple(coord)
    except TypeError:
        coord_iter = (coord,)
    if len(coord_iter) != len(self.axes):
        raise ValueError(f"Coordinate dimensionality {len(coord_iter)} does not match histogram dimensionality {len(self.axes)}.")
    indices = []

    # Convert each coordinate to an integer bin index
    for ax, c in zip(self.axes, coord_iter):
        idx = None
        # Prefer a dedicated bin-finding method if available
        if hasattr(ax, "coord_to_index"):
            idx = ax.coord_to_index(c)
        elif hasattr(ax, "find_bin"):
            idx = ax.find_bin(c)
        elif hasattr(ax, "__call__"):
            try:
                idx = ax(c)
            except Exception:
                idx = None
        # If no suitable method found, raise an informative error
        if idx is None:
            raise AttributeError(f"Axis object {ax!r} must provide a method to convert a coordinate to an integer bin index.")
        # Ignore out-of-range coordinates
        if idx < 0 or idx >= ax.size:
            return
        indices.append(idx)

    # Increment the appropriate bin (assuming self.data is a NumPy array)
    self.data[tuple(indices)] += weight

