        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        # Accept single coordinate values for 1‑D histograms
        if not isinstance(coord, (list, tuple)):
            coord = (coord,)

        # Ensure the dimension matches
        if len(coord) != len(self.axes):
            raise ValueError("Coordinate dimensionality does not match histogram.")

        bin_indices = []
        for ax, c in zip(self.axes, coord):
            # Try a custom binning method if the axis provides one
            try:
                idx = ax.bin(c)  # returns None if out of range
            except Exception:
                # Fallback: assume the axis has an 'edges' attribute
                try:
                    idx = np.searchsorted(ax.edges, c, side='right') - 1
                except AttributeError:
                    raise RuntimeError("Axis object does not provide binning information.")
            # If the value lies outside the defined bins, ignore the fill
            if idx is None or idx < 0 or idx >= len(ax.edges) - 1:
                return
            bin_indices.append(idx)

        # Increment the bin by the weight (weight may be a scalar or array)
        self.data[tuple(bin_indices)] += weight

