def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generates a partial observer schema dictionary from a Kubernetes manifest dictionary.
    For non-list and non-dict scalar values, substitutes None. For top-level dictionaries
    (first_level=True), preserves values of key identifying fields.
    """
    # Define identifying fields that should be preserved at the top-level
    identifying_fields = {"apiVersion", "kind"}

    # Initialize the resulting schema dictionary
    schema_dict = {}

    # Preserve the identifying fields at the top-level, if requested
    if first_level:
        for field in identifying_fields:
            if field in manifest_dict:
                schema_dict[field] = manifest_dict[field]

    # Iterate over all keys in the manifest dictionary
    for key, value in manifest_dict.items():
        # Skip already handled identifying fields when tracing top-level logic
        if first_level and key in identifying_fields:
            continue

        if isinstance(value, dict):
            # Recurse for nested dictionaries
            schema_dict[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Delegate list handling to the appropriate helper function
            # (Assumes generate_default_observer_schema_list exists in the same module)
            schema_dict[key] = generate_default_observer_schema_list(value, first_level=False)
        else:
            # Replace scalar values with None, unless it's a top-level identifying field
            if not (first_level and key in identifying_fields):
                schema_dict[key] = None

    return schema_dict

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generate a default observer_schema dictionary from a Kubernetes manifest.

    Parameters
    ----------
    manifest_dict : dict
        Partial Kubernetes resource dictionary.
    first_level : bool, optional
        If True, the dictionary represents the top-level observer schema for a
        Kubernetes resource. In this case, identifying fields such as
        ``apiVersion`` and ``kind`` are preserved instead of being set to None.

    Returns
    -------
    dict
        A new dictionary mirroring the structure of ``manifest_dict`` but with all
        non-dict and non-list leaf values replaced by ``None``. Identifying fields
        are retained when ``first_level`` is True.
    """
    _IDENTIFYING_KEYS = {"apiVersion", "kind"}

    def _recurse(value):
        if isinstance(value, dict):
            return {k: _recurse(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_recurse(v) for v in value]
        return None

    if not first_level:
        # Simple deep copy with leaf values replaced by None
        return _recurse(manifest_dict)

    # Top-level: preserve values of identifying keys
    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, (dict, list)):
            result[key] = _recurse(value)
        else:
            if key in _IDENTIFYING_KEYS:
                result[key] = value
            else:
                result[key] = None
    return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generate a default observer schema dictionary from a Kubernetes manifest dictionary.

    The resulting dictionary has the same structure as the input but all scalar
    (non-dict / non-list) values are replaced by ``None``.  When ``first_level`` is
    ``True``, the values of the identifying fields are preserved from the input
    manifest.  The identifying fields are the top‑level scalar fields
    ``apiVersion`` and ``kind`` and the nested ``metadata`` fields ``name`` and
    ``namespace``.
    """
    def _recurse(data, path=()):
        if isinstance(data, dict):
            out = {}
            for key, value in data.items():
                if isinstance(value, (dict, list)):
                    out[key] = _recurse(value, path + (key,))
                else:
                    # Preserve identifying fields when generating the root schema
                    if first_level:
                        if not path:  # top level
                            if key in ("apiVersion", "kind"):
                                out[key] = value
                                continue
                        if path == ("metadata",):
                            if key in ("name", "namespace"):
                                out[key] = value
                                continue
                    out[key] = None
            return out
        elif isinstance(data, list):
            return [_recurse(item, path) for item in data]
        else:
            return None

    return _recurse(manifest_dict)

