def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Update a partial `last_applied_manifest` dict from a partial Kubernetes
    response according to the supplied `observer_schema`.

    The function recursively walks through all observed fields described by
    `observer_schema`. For each field it:
      * raises a KeyError if the field is missing from the response;
      * if the field refers to a nested dictionary (the schema value is a dict)
        it ensures a corresponding dict exists in `last_applied_manifest`
        and recursively updates that nested dict;
      * otherwise it sets the field in `last_applied_manifest` to the value
        from the response, but only if the field is not already present.
    """
    for field, field_schema in observer_schema.items():
        if field not in response:
            raise KeyError(f"Key '{field}' is missing from the Kubernetes response.")
        resp_val = response[field]
        # If the field's schema is a dict, we expect a nested dict
        if isinstance(field_schema, dict):
            # Prepare nested container in last_applied_manifest if absent
            if field not in last_applied_manifest or not isinstance(last_applied_manifest[field], dict):
                last_applied_manifest[field] = {}
            # Recursively process nested fields
            # NOTE: If the response value isn't a dict, we still proceed, as
            # the schema dictates nested structure but the actual response
            # might be empty or absent.
            if isinstance(resp_val, dict):
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[field], field_schema, resp_val
                )
            else:
                # When the schema expects a dict but the response gives a
                # non-dict value (e.g., None), leave the existing nested dict.
                pass
        else:
            # For leaf fields, set the value only if it hasn't been set yet.
            if field not in last_applied_manifest:
                last_applied_manifest[field] = resp_val

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.
    """
    # Ensure the application spec has a manifest and an observer_schemas place to store defaults
    manifest = getattr(app.spec, "manifest", [])
    if not isinstance(manifest, list):
        manifest = []
    # Will collect default schemas in this dict
    default_schemas = {}
    # Walk through each resource manifest
    for resource in manifest:
        if not isinstance(resource, dict):
            continue
        kind = resource.get("kind")
        metadata = resource.get("metadata") or {}
        name = metadata.get("name")
        # Skip resources that lack a clear identity
        if not kind or not name:
            continue
        key = f"{kind}/{name}"
        # If user already defined a custom schema for this resource, skip
        if getattr(app.spec, "observer_schemas", None) and key in app.spec.observer_schemas:
            continue
        # Build a minimal default schema that captures apiVersion, kind, metadata, and spec
        default_schema = {
            "apiVersion": resource.get("apiVersion", ""),
            "kind": kind,
            "metadata": {
                "name": name,
                "namespace": metadata.get("namespace", ""),
                # Preserve any labels/annotations that might be relevant for observation
                **{k: v for k, v in metadata.items() if k in ["labels", "annotations"]},
            },
            "spec": resource.get("spec", {}),
        }
        default_schemas[key] = default_schema
    # Merge the calculated defaults into the application's spec.observer_schemas
    if getattr(app.spec, "observer_schemas", None) is not None:
        app.spec.observer_schemas.update(default_schemas)
    else:
        app.spec.observer_schemas = default_schemas
    return default_schemas

def format(
    self,
    sql,
    params,
):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`collections.abc.Mapping` or :class:`collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   The set of converted out-style parameters (:class:`dict` or
        :class:`list`).
    """
    # Determine types
    if isinstance(params, dict):
        in_named = True
    elif isinstance(params, (list, tuple)):
        in_named = False
    else:
        raise ValueError("params must be a mapping or a sequence")

    # If OUT style is same as IN style, just return original
    if self.out_style == self.in_style:
        return (sql, params)

    # Helper to process str-like
    def _process_str(sql_str: str) -> Tuple[str, List]:
        if self.out_style == "named" and not in_named:
            # Convert ordinal placeholders '?' to named ones
            new_sql_parts = []
            param_index = 1
            for ch in sql_str:
                if ch == "?":
                    new_sql_parts.append(f":param{param_index}")
                    param_index += 1
                else:
                    new_sql_parts.append(ch)
            return ("".join(new_sql_parts), list(params))
        elif self.out_style == "ordinal" and in_named:
            # Convert named placeholders ':name' to ordinal '?'
            import re
            pattern = re.compile(r":(\w+)")
            new_sql_parts = []
            last_end = 0
            new_params = []
            for m in pattern.finditer(sql_str):
                name = m.group(1)
                new_sql_parts.append(sql_str[last_end:m.start()])
                new_sql_parts.append("?")
                # Ensure param exists
                if name not in params:
                    raise KeyError(f"Parameter name '{name}' not found in params")
                new_params.append(params[name])
                last_end = m.end()
            new_sql_parts.append(sql_str[last_end:])
            return ("".join(new_sql_parts), new_params)
        else:
            # Unsupported conversion
            raise ValueError(f"Unsupported conversion style: {self.in_style} -> {self.out_style}")

    # Handle bytes
    if isinstance(sql, bytes):
        decoded_sql = sql.decode("utf-8")
        formatted_sql_str, new_params = _process_str(decoded_sql)
        return (formatted_sql_str.encode("utf-8"), new_params)

    # Handle str
    if isinstance(sql, str):
        return _process_str(sql)

    raise TypeError("sql must be str or bytes")

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    decoder = (lambda s: s.decode("utf-8") if isinstance(s, (bytes, bytearray)) else s)
    encoder = (lambda s: s.encode("utf-8") if isinstance(s, str) else s)
    decoded_sql = decoder(sql)
    # Determine placeholder format
    in_style = self.in_style
    out_style = self.out_style if hasattr(self, "out_style") else self.in_style
    # Simplified conversion: replace in_style tokens with out_style tokens
    if isinstance(in_style, str) and len(in_style) == 1:
        # simple single char placeholder
        converted_sql = decoded_sql.replace(in_style, out_style)
    else:
        # assume named style e.g., ":name" or "%(name)s"
        # replace the base token
        base_token = in_style
        converted_sql = decoded_sql.replace(base_token, out_style)
    params_list: List[Union[Dict[Union[str, int], Any], List[Any]]] = []
    for params in many_params:
        if isinstance(params, Mapping):
            # Escape parameter names if needed
            try:
                escaped_params = {self.escape(key) if hasattr(self, "escape") else key: value
                                  for key, value in params.items()}
            except Exception:
                escaped_params = params
            params_list.append(escaped_params)
        else:
            # sequence of values
            try:
                converted = list(params)
            except TypeError:
                converted = [params]
            params_list.append(converted)
    return encoder(converted_sql), params_list

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    from pathlib import Path
    import json

    p = Path(path).expanduser()
    if not p.exists():
        return False

    # Locate the manifest file (could be in .ocfl/manifest.json or ocfl-manifest.json)
    possible_manifests = [p / ".ocfl" / "manifest.json", p / "ocfl-manifest.json", p / "manifest.json"]
    manifest_path = next((mp for mp in possible_manifests if mp.is_file()), None)
    if not manifest_path:
        return False

    try:
        with manifest_path.open(encoding="utf-8") as f:
            manifest = json.load(f)
    except Exception:
        return False

    # Basic required keys in manifest
    required_keys = {"object", "version", "files"}
    if not required_keys.issubset(manifest):
        return False

    # The content directory should exist
    content_dir = p / "content"
    if not content_dir.is_dir():
        return False

    # Validate each file referenced in the manifest
    for entry in manifest.get("files", []):
        if not isinstance(entry, dict):
            return False

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os, json

    # Helper to check if a directory is an OCFL object (has .ocfl-info)
    def is_ocfl_object(p):
        return os.path.isdir(p) and os.path.exists(os.path.join(p, ".ocfl-info"))

    # If path is an OCFL object, validate it
    if is_ocfl_object(path):
        try:
            # Verify .ocfl-info is valid JSON
            with open(os.path.join(path, ".ocfl-info"), "r", encoding="utf-8") as f:
                json.load(f)
        except Exception:
            return False

        # Iterate through top-level directories (path objects)
        for top_dir in os.listdir(path):
            # Skip hidden or system directories
            if top_dir.startswith("."):
                continue
            top_path = os.path.join(path, top_dir)
            if not os.path.isdir(top_path):
                continue

            # Find version directories (numeric names)
            vdirs = [d for d in os.listdir(top_path) if d.isdigit() and os.path.isdir(os.path.join(top_path, d))]
            if not vdirs:
                continue  # no versions, skip

            # Validate the latest version
            latest_v = max(vdirs, key=lambda d: int(d))
            latest_path = os.path.join(top_path, latest_v)

            # Check existence of expected subdirectories
            for sub in ("metadata", "content"):
                sub_path = os.path.join(latest_path, sub)
                if not os.path.isdir(sub_path):
                    # Missing expected directory – invalid
                    return False

            # Optional: basic checks on metadata directory
            # (e.g., at least one file exists)
            try:
                if not os.listdir(os.path.join(latest_path, "metadata")):
                    return False
            except Exception:
                return False

        return True

    # Otherwise, treat the path as a possible OCFL root
    if os.path.isdir(path):
        valid = True
        for entry in os.listdir(path):
            entry_path = os.path.join(path, entry)
            if os.path.isdir(entry_path):
                if is_ocfl_object(entry_path):
                    if not self.validate(entry_path):
                        valid = False
                        break
        return valid

    # Path does not exist or is not a directory
    return False

def validate(self, path):
        """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        try:
            if not os.path.isdir(path):
                return False
            index_dir = os.path.join(path, 'index')
            if not os.path.isdir(index_dir):
                return False
            manifest_path = os.path.join(index_dir, 'manifest.json')
            if not os.path.isfile(manifest_path):
                return False
            with open(manifest_path, 'r', encoding='utf-8') as f:
                data = json.load(f)
            if 'ocfl_version' not in data or 'content' not in data:
                return False
            for cid in data.get('content', []):
                obj_path = os.path.join(index_dir, cid.get('path', ''))
                if not os.path.isfile(obj_path):
                    return False
            return True
        except Exception:
            return False

