    """
    Return a human‑readable status string for the validator, optionally prefixed.
    The method tries to use common attributes/methods that a validator
    implementation might expose: `is_valid()`, `valid`, `errors`, `error`,
    and `status`. It gracefully falls back when an attribute is missing.
    """
    # Determine if the validator considers itself valid.
    if hasattr(self, 'is_valid'):
        try:
            valid = self.is_valid()
        except Exception:
            valid = False
