        valid = getattr(self, 'valid', False)

    if valid:
        return f"{prefix}OK"

    # Gather error messages if any.
    errors = []
    if hasattr(self, 'errors'):
        # Assume self.errors is iterable.
        try:
            errors = list(self.errors)
        except Exception:
            try:
                errors = [self.errors]
            except Exception:
                pass
    elif hasattr(self, 'error'):
        errors = [self.error]

