        "1.0": {"name", "type", "items"},
        "2.0": {"name", "type", "items", "description"},
        "3.0": {"name", "type", "items", "description", "metadata"},
    }

    # If we have a spec version not in the mapping, raise an error
    if spec_version not in required_fields:
        raise ValueError(f"Unsupported specification version '{spec_version}'")

    # Validate required top‑level keys
    missing = required_fields[spec_version] - inventory.keys()
    if missing:
        missing_list = ", ".join(sorted(missing))
        raise ValueError(f"Missing required inventory keys for version {spec_version}: {missing_list}")

    # Basic validation of the items list
    items = inventory["items"]
    if not isinstance(items, (list, tuple)):
        raise TypeError("inventory['items'] must be a list or tuple")
    if not items:
        raise ValueError("inventory['items'] must contain at least one item")

    # Validate each item structure
    for idx, item in enumerate(items):
        if not isinstance(item, dict):
            raise TypeError(f"Item at index {idx} must be a dict")
        # Each item must have a 'name'; other fields are optional unless required by spec
        if "name" not in item:
            raise ValueError(f"Item at index {idx} is missing required field 'name'")
        # Optional check for numeric version field if spec_version >= 2.0
        if spec_version in ("2.0", "3.0") and ("version" in item):
            if not isinstance(item["version"], str):
                raise TypeError(f"Item at index {idx} 'version' field must be a string")

    # Return the validated inventory (or True)
    return True

