            # Compare versions
            try:
                self_ver = _parse_version(self_pkg.get("version"))
                prior_ver = _parse_version(prior_pkg.get("version"))
            except Exception as exc:
                raise ValueError(f"Error parsing versions for package {pkg_name}: {exc}")

            if self_ver <= prior_ver:
                raise ValueError(
                    f"Package '{pkg_name}' has same or older version in current inventory "
                    f"({self_ver}) compared to prior ({prior_ver})."
                )

            # Optionally check other consistency criteria (e.g., name, location)
            if self_pkg.get("name") != prior_pkg.get("name"):
                raise ValueError(
                    f"Package name mismatch for '{pkg_name}': "
                    f"'{self_pkg.get('name')}' vs '{prior_pkg.get('name')}'."
                )

        if missing_in_self:
            raise ValueError(
                f"The following packages from the prior inventory are missing in the current inventory: "
                f"{', '.join(missing_in_self)}"
            )

        return True

