def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.
    """
    import os

    # Obtenha o nome do arquivo a partir do caminho completo
    file_name = os.path.basename(file_path)

    # Detecta o tipo do arquivo baseado em sufixo
    # Espera-se que o arquivo tenha extensões .asset ou .rendition
    if file_name.lower().endswith('.asset'):
        file_type = 'asset'
    elif file_name.lower().endswith('.rendition'):
        file_type = 'rendition'
    else:
        # Caso não corresponda a um tipo esperado, coloca como desconhecido
        file_type = 'unknown'

    # Atualiza o dicionário de pacotes (supondo que exista globalmente)
    # Se não houver, cria um novo dicionário
    try:
        packages[prefix]
    except NameError:
        global packages
        packages = {}
    packages[prefix] = {
        'type': file_type,
        'path': file_path
    }

    # Retorna os dados do arquivo analisado
    return {
        'prefix': prefix,
        'type': file_type,
        'path': file_path
    }

def add_rendition(self, lang, file_path):
    """
    {
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }
    """
    if not hasattr(self, "_renditions"):
        self._renditions = {}
    # Extract the file name from the path
    basename = file_path.split("/")[-1]
    # Determine the original filename by removing the language suffix if present
    if f"-{lang}" in basename:
        original = basename.replace(f"-{lang}", "")
    else:
        original = basename
    # Ensure a dictionary exists for this original file
    entry = self._renditions.setdefault(original, {})
    # Store the original name and the language-specific rendition
    entry["original"] = original
    entry[lang] = basename

