def pretty(self, indent=0, debug=False):
        """
        Return a pretty formatted representation of self.
        Each node is left-aligned according to its depth in the tree.
        If `debug` is True, the representation includes the full repr of each node.
        Assumes that a node may provide a `children()` method that returns an iterable
        of child nodes, or otherwise it falls back to inspecting its `__dict__`.
        """
        def _format(node, level):
            ind = '    ' * level
            # Basic description of the node
            if debug:
                desc = f"{node.__class__.__name__} ({repr(node)})"
            else:
                desc = node.__class__.__name__
            lines = [f"{ind}{desc}"]
            # Preferred child traversal
            children_iter = None
            if hasattr(node, "children") and callable(getattr(node, "children")):
                try:
                    children_iter = node.children()
                except Exception:
                    children_iter = None
            # If children() not available, fallback to attributes
            if children_iter is not None:
                for child in children_iter:
                    lines.append(_format(child, level + 1))
            else:
                for attr, val in getattr(node, "__dict__", {}).items():
                    if attr.startswith('_'):          # Skip private/internal attrs
                        continue
                    if isinstance(val, (list, tuple)):
                        lines.append(f"{ind}    {attr}:")
                        for item in val:
                            lines.append(_format(item, level + 2))
                    else:
                        lines.append(f"{ind}    {attr}: {val}")
            return '\n'.join(lines)

        return _format(self, indent)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    :param indent: current indentation level (used for recursion)
    :param debug: if True, add type annotations to each value
    :return: multiline string describing the object
    """
    def format_value(name, value, ind):
        """Recursively format a field value."""
        space = ' ' * (ind * 4)
        prefix = f"{space}{name} = "

        # Detect if the value itself has a pretty method
        if hasattr(value, 'pretty') and callable(value.pretty):
            pretty_str = value.pretty(indent=ind + 1, debug=debug)
            # prepend the field name to the first line
            pretty_lines = pretty_str.splitlines()
            pretty_lines[0] = f"{prefix}{pretty_lines[0].strip()}"
            return "\n".join(pretty_lines)

        # List or tuple: format each element
        if isinstance(value, (list, tuple)):
            if not value:
                return f"{prefix}[]"
            lines = [f"{prefix}["]
            for idx, item in enumerate(value):
                lines.append(format_value(f"[{idx}]", item, ind + 1))
            lines.append(f"{space}]")
            return "\n".join(lines)

        # Dictionary: format each key/value pair
        if isinstance(value, dict):
            if not value:
                return f"{prefix}{{}}"
            lines = [f"{prefix}{{"]
            for k, v in value.items():
                lines.append(format_value(str(k), v, ind + 1))
            lines.append(f"{space}}}")
            return "\n".join(lines)

        # Primitive types
        val_repr = repr(value)
        if debug:
            val_repr += f"  # {type(value).__name__}"
        return f"{prefix}{val_repr}"

    # Start the representation with the class name
    lines = [f"{self.__class__.__name__} {{"]
    for field in sorted(vars(self)):
        lines.append(format_value(field, getattr(self, field), indent + 1))
    lines.append("}")
    return "\n".join(lines)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    visited = set()

    def _format(obj, level):
        # Handle recursion
        oid = id(obj)
        if oid in visited:
            return "<Recursion>"
        visited.add(oid)

        pref = " " * (level * 4)
        if isinstance(obj, (str, int, float, bool, type(None))):
            return repr(obj)

        if isinstance(obj, (list, tuple, set)):
            open_char = "[" if isinstance(obj, list) else "(" if isinstance(obj, tuple) else "{"
            close_char = "]" if isinstance(obj, list) else ")" if isinstance(obj, tuple) else "}"
            if not obj:
                return open_char + close_char
            parts = []
            for item in obj:
                parts.append(pref + "    " + _format(item, level + 1))
            inner = ",\n".join(parts)
            return f"{open_char}\n{inner}\n{pref}{close_char}"

        if isinstance(obj, dict):
            if not obj:
                return "{}"
            parts = []
            for k, v in obj.items():
                parts.append(pref + "    " + f"{repr(k)}: {_format(v, level + 1)}")
            inner = ",\n".join(parts)
            return f"{{\n{inner}\n{pref}}}"

        if hasattr(obj, "__dict__"):
            attrs = obj.__dict__
            if not attrs:
                return f"{obj.__class__.__name__}()"
            parts = []
            for k, v in attrs.items():
                parts.append(pref + "    " + f"{k}: {_format(v, level + 1)}")
            inner = ",\n".join(parts)
            return f"{obj.__class__.__name__}(\n{inner}\n{pref})"

        # Fallback for other types
        return repr(obj)

    return _format(self, indent)

def pretty(self, indent=0, debug=False):
        prefix = ' ' * indent
        lines = []
        # Show class name and optionally id for debugging
        if debug:
            lines.append(f"{prefix}{self.__class__.__name__}@{id(self):#x}")
        else:
            lines.append(f"{prefix}{self.__class__.__name__}")
        # Iterate over instance attributes
        for name, val in self.__dict__.items():
            # If the attribute itself can be pretty‑printed, recurse
            if hasattr(val, "pretty") and callable(val.pretty):
                lines.append(f"{prefix}  {name}:")
                child_str = val.pretty(indent + 4, debug)
                lines.extend(child_str.splitlines())
            # Handle sequences
            elif isinstance(val, (list, tuple)):
                lines.append(f"{prefix}  {name}: [")
                for item in val:
                    if hasattr(item, "pretty") and callable(item.pretty):
                        child_str = item.pretty(indent + 6, debug)
                        lines.extend(child_str.splitlines())
                    else:
                        lines.append(f"{' ' * (indent + 6)}{repr(item)}")
                lines.append(f"{prefix}  ]")
            # Handle dictionaries
            elif isinstance(val, dict):
                lines.append(f"{prefix}  {name}: {{")
                for k, v in val.items():
                    if hasattr(v, "pretty") and callable(v.pretty):
                        lines.append(f"{' ' * (indent + 6)}{repr(k)}:")
                        child_str = v.pretty(indent + 8, debug)
                        lines.extend(child_str.splitlines())
                    else:
                        lines.append(f"{' ' * (indent + 6)}{repr(k)}: {repr(v)}")
                lines.append(f"{prefix}  }}")
            # Fallback for other types
            else:
                lines.append(f"{prefix}  {name}: {repr(val)}")
        return '\n'.join(lines)

def on(self, hook):
    """Decorator function to add a new handler to the registry.
    Args:
        hook (HookType): Hook attribute for which to register the handler.
    Returns:
        callable: Decorator for registering listeners for the specified hook.
    """
    def decorator(func):
        if not hasattr(self, "_registry"):
            self._registry = {}
        self._registry.setdefault(hook, []).append(func)
        return func
    return decorator

