def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Determine the sequence of values to use
    order = ['major', 'minor', 'patch', 'prerelease', 'build']
    if isinstance(pieces, dict):
        values = [pieces.get(k) for k in order]
    elif isinstance(pieces, list):
        # Accept a list of values or a list of (label, value) tuples
        if all(isinstance(p, tuple) and len(p) == 2 for p in pieces):
            values = [v for _, v in pieces]
        else:
            values = pieces
    else:
        raise TypeError("pieces must be a dict or a list")

    # Helper formatters for each style
    def fmt_full():
        return ".".join(str(v) for v in values[:3] if v is not None)

    def fmt_short():
        return ".".join(str(v) for v in values[:2] if v is not None)

    def fmt_dotted():
        return ".".join(str(v) for v in values if v is not None)

    def fmt_dash():
        return "-".join(str(v) for v in values if v is not None)

    def fmt_semver():
        base = ".".join(str(v) for v in values[:3] if v is not None)
        prerelease = values[3]
        build = values[4]
        if prerelease:
            base += f"-{prerelease}"
        if build:
            base += f"+{build}"
        return base

    style_map = {
        'full': fmt_full,
        'short': fmt_short,
        'dotted': fmt_dotted,
        'dash': fmt_dash,
        'semver': fmt_semver,
    }

    if style not in style_map:
        raise ValueError(f"Unsupported style: {style}")

    return style_map[style]()

