def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    import os
    import hashlib

    # Path to the root of the storage hierarchy
    root_path = getattr(self, 'root_path', None)
    if root_path is None:
        raise AttributeError("The instance must have a 'root_path' attribute.")

    num_objects = 0
    good_objects = 0

    # Walk through the directory tree
    for dirpath, _, filenames in os.walk(root_path):
        for fname in filenames:
            full_path = os.path.join(dirpath, fname)
            # Relative path used as key for digests if available
            rel_path = os.path.relpath(full_path, root_path)

            num_objects += 1
            object_ok = True

            # Validate that the object exists (basic existence check)
            if validate_objects:
                if not os.path.isfile(full_path):
                    object_ok = False
                    if show_warnings:
                        print(f"[WARNING] Object missing or not a file: {rel_path}")

            # Validate digest if a digest source is available
            if check_digests and hasattr(self, 'digests') and isinstance(self.digests, dict):
                expected_digest = self.digests.get(rel_path)
                if expected_digest is not None:
                    # Compute MD5 digest of the file
                    md5 = hashlib.md5()
                    try:
                        with open(full_path, 'rb') as f:
                            for chunk in iter(lambda: f.read(8192), b''):
                                md5.update(chunk)
                        actual_digest = md5.hexdigest()
                        if actual_digest != expected_digest:
                            object_ok = False
                            if show_warnings:
                                print(f"[WARNING] Digest mismatch for {rel_path}")
                    except (OSError, IOError) as e:
                        object_ok = False
                        if show_warnings:
                            print(f"[WARNING] Unable to read {rel_path} for digest check: {e}")

            if object_ok:
                good_objects += 1

    return num_objects, good_objects

