def next_version(version):
    """Return the next version identifier, preserving leading zeros in each segment."""
    if not version:
        return version
    parts = version.split('.')
    ints = []
    widths = []
    for p in parts:
        # Capture original width if there were leading zeros
        if p.lstrip('0') == '':
            # all zeros
            ints.append(0)
            widths.append(len(p))
        else:
            ints.append(int(p))
            if p.startswith('0'):
                widths.append(len(p))
            else:
                widths.append(None)
    # Increment the last segment
    ints[-1] += 1
    # Reconstruct the version string with preserved width where appropriate
    out_parts = []
    for val, w in zip(ints, widths):
        s = str(val)
        if w is not None:
            s = s.rjust(w, '0')
        out_parts.append(s)
    return '.'.join(out_parts)

def next_version(version):
    """Return the next version string, preserving original zero‑padding and an optional leading 'v'."""
    if not version:
        return version

    # Preserve an optional leading 'v' prefix
    prefix = ""
    if version[0] == "v":
        prefix = "v"
        version = version[1:]

    parts = version.split(".")
    # Find the right‑most numeric part to increment
    last_idx = None
    for idx, part in enumerate(parts):
        if part.isdigit():
            last_idx = idx
    if last_idx is None:
        # No numeric component to increment; return as is
        return prefix + ".".join(parts)

    part = parts[last_idx]
    width = len(part)
    new_num = int(part) + 1
    new_part = str(new_num).zfill(width)
    parts[last_idx] = new_part

    return prefix + ".".join(parts)

def validate_version_inventories(self, version_dirs):
        """
        Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        import os

        # Helper to parse an inventory file into a dict: {path: digest}
        def _parse_inventory(inv_path):
            entries = {}
            if not os.path.exists(inv_path):
                raise FileNotFoundError(f"Inventory file not found: {inv_path}")
            with open(inv_path, "r", encoding="utf-8") as fh:
                for line in fh:
                    line = line.strip()
                    if not line or line.startswith("#"):
                        continue
                    parts = line.split(None, 1)
                    if len(parts) != 2:
                        continue  # or raise ValueError
                    digest, rel_path = parts
                    entries[rel_path] = digest
            return entries

        # Parse the root inventory (assumed in the repository root)
        root_inventory = _parse_inventory(os.path.join(self.root_dir, "inventory"))

        # Record digests that differ between a version inventory and the root
        mismatched_digests = {}

        for vdir in version_dirs:
            inv_path = os.path.join(self.root_dir, vdir, "inventory")
            # Ensure the inventory exists for this version directory
            if not os.path.isfile(inv_path):
                raise FileNotFoundError(f"Missing inventory in version directory '{vdir}'")

            # Load the inventory for this version
            v_inv = _parse_inventory(inv_path)

            # Check each entry against the root inventory
            for rel_path, digest in v_inv.items():
                root_digest = root_inventory.get(rel_path)
                if root_digest and root_digest != digest:
                    mismatched_digests.setdefault(rel_path, []).append(vdir)

        # Store the mismatches for later validation steps
        self.digests_different = mismatched_digests

        # Optionally, log or raise an error if mismatches were found
        if mismatched_digests:
            first_issue = next(iter(mismatched_digests))
            raise ValueError(
                f"Digest mismatch for '{first_issue}' between root and version directories: "
                f"{mismatched_digests[first_issue]}"
            )

def validate_version_inventories(self, version_dirs):
    import os
    import json

    # Dictionary to record digests that differ from the root inventory
    # Format: {relative_path: [(version, version_digest, root_digest), ...]}
    self.different_digests = {}

    # Load the root inventory once (assumed to be a JSON file in the root directory)
    root_inv_path = os.path.join(self.root_path, "inventory.json")
    try:
        with open(root_inv_path, "r", encoding="utf-8") as f:
            root_inventory = json.load(f)
    except Exception:
        root_inventory = {}
    # Ensure errors list exists
    if not hasattr(self, "errors"):
        self.errors = []

    for version_index, version_name in enumerate(version_dirs, start=1):
        version_path = os.path.join(self.root_path, version_name)
        inv_file = os.path.join(version_path, "inventory.json")

        # 1. Check that the inventory file exists
        if not os.path.isfile(inv_file):
            self.errors.append(f"[{version_name}] Missing inventory.json")
            continue

        # 2. Load this version's inventory
        try:
            with open(inv_file, "r", encoding="utf-8") as f:
                version_inventory = json.load(f)
        except Exception as e:
            self.errors.append(f"[{version_name}] Unable to read inventory.json: {e}")
            continue

        # 3. Determine expected file set for this version (all files under the directory except the inventory file)
        expected_files = set()
        for dirpath, _, filenames in os.walk(version_path):
            for fname in filenames:
                # Skip the inventory file itself
                if fname == "inventory.json":
                    continue
                # Build relative path from the version directory root
                rel_path = os.path.relpath(os.path.join(dirpath, fname), version_path)
                expected_files.add(rel_path)

        # 4. Validate that the inventory lists all expected files
        inventory_files = set(version_inventory.keys())

        missing_files = expected_files - inventory_files
        if missing_files:
            self.errors.append(
                f"[{version_name}] Inventory missing entries for: {', '.join(sorted(missing_files))}"
            )

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure we have a place to store digests that differ from the root inventory
    if not hasattr(self, '_diff_digests'):
        self._diff_digests = {}

    root_inventory = getattr(self, 'root_inventory', {})
    if not isinstance(root_inventory, dict):
        raise ValueError("root_inventory must be a dict mapping file paths to digests")

    # Expected inventory filename (may be extended as needed)
    inventory_filenames = {"inventory.json", "inventory.txt", "inventory"}
    for idx, dir_path in enumerate(version_dirs, start=1):
        # Locate inventory file inside the version directory
        inv_path = None
        for name in inventory_filenames:
            candidate = os.path.join(dir_path, name)
            if os.path.isfile(candidate):
                inv_path = candidate
                break
        if not inv_path:
            raise FileNotFoundError(f"Missing inventory file in version directory '{dir_path}'")

        # Load the inventory data
        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                inv_content = json.load(f)
        except Exception as exc:
            raise ValueError(f"Failed to load inventory at '{inv_path}': {exc}")

        if not isinstance(inv_content, dict):
            raise ValueError(f"Inventory format in '{inv_path}' is expected to be a JSON object")

        # Validate that every entry in this inventory exists in the root inventory
        for path, digest in inv_content.items():
            if path not in root_inventory:
                # The file is unknown in the root inventory – this is an error
                raise KeyError(f"File '{path}' in inventory of version {idx} "
                               f"not present in root inventory")

            # Record when a digest differs from the root inventory
            if digest != root_inventory[path]:
                self._diff_digests.setdefault(path, set()).add(digest)

def find_path_type(path):
    import os, re
    if not os.path.exists(path):
        return "Path does not exist"
    if os.path.isfile(path):
        return "file"
    if os.path.isdir(path):
        try:
            entries = os.listdir(path)
        except OSError as e:
            return f"Error listing directory: {e}"
        pattern = re.compile(r'^0=')
        root_candidate = False
        object_candidate = False
        for e in entries:
            if pattern.match(e):
                full = os.path.join(path, e)
                if os.path.isdir(full):
                    root_candidate = True
                elif os.path.isfile(full):
                    object_candidate = True
        if root_candidate and not object_candidate:
            return "root"
        if object_candidate:
            return "object"
        return "No Namaste files found"
    return "Unrecognized path type"

