    """
    Give each subparser a chance to parse all arguments and return the parsed namespaces
    plus a list of arguments not consumed by any subparser.
    """
    parsed = {}
    unknown_sets = []

    for name, parser in subparsers.items():
        # parse_known_args will return (namespace, list of unknown args)
        namespace, unknown = parser.parse_known_args(unparsed_arguments)
        parsed[name] = namespace
        unknown_sets.append(set(unknown))

    # Arguments that are unknown to every subparser
    if unknown_sets:
        remaining_set = set.intersection(*unknown_sets)
    else:
        remaining_set = set()

    # Preserve original order
    remaining = [arg for arg in unparsed_arguments if arg in remaining_set]
    return parsed, remaining

