    For duplicates where both values are MappingNode, perform a deep merge of the mappings.
    For other duplicate types, the later value wins.
    """
    # Helper to merge two MappingNode objects.
    def merge_mapping_nodes(a, b):
        # Keep tag from the first mapping node.
        merged_pairs = list(a.value)
        key_to_pos = {}
        for idx, (k, v) in enumerate(a.value):
            key_to_pos[k.value] = idx
        for k, v in b.value:
            key = k.value
            if key in key_to_pos:
                idx = key_to_pos[key]
                merged_pairs[idx] = (merged_pairs[idx][0], v)  # keep original key node
            else:
                merged_pairs.append((k, v))
                key_to_pos[key] = len(merged_pairs) - 1
        return MappingNode(tag=a.tag, value=merged_pairs)

    # Track merged values and key nodes.
    merged_values = {}
    key_nodes = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged_values:
            existing = merged_values[key]
            if isinstance(existing, MappingNode) and isinstance(value_node, MappingNode):
                merged_values[key] = merge_mapping_nodes(existing, value_node)
            else:
                merged_values[key] = value_node
        else:
            merged_values[key] = value_node
            key_nodes[key] = key_node

    # Preserve the order of the first appearance of each key.
    ordered_keys = list(key_nodes.keys())
    return [(key_nodes[k], merged_values[k]) for k in ordered_keys]

def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode, Node) tuples, merging MappingNode values
    of duplicate keys recursively.  For non-mapping values the last one wins.
    """
    # Helper to merge two MappingNode objects
    def merge_mapping_nodes(node1, node2):
        # Create a mapping from existing key values to (key_node, value_node)
        merged = {}
        for k_node, v_node in node1.value:
            merged[k_node.value] = (k_node, v_node)
        for k_node, v_node in node2.value:
            key = k_node.value
            if key in merged:
                orig_k_node, orig_v_node = merged[key]
                # Recursive merge if both values are MappingNode instances
                if (
                    isinstance(orig_v_node, ruamel.yaml.nodes.MappingNode)
                    and isinstance(v_node, ruamel.yaml.nodes.MappingNode)
                ):
                    merged[key] = (
                        orig_k_node,
                        merge_mapping_nodes(orig_v_node, v_node),
                    )
                else:
                    # last value wins
                    merged[key] = (k_node, v_node)
            else:
                merged[key] = (k_node, v_node)
        # Preserve order: node1's order followed by any new keys from node2
        merged_list = []
        for k_node, v_node in node1.value:
            if k_node.value in merged:
                merged_list.append(merged[k_node.value])
        for k_node, v_node in node2.value:
            if k_node.value not in [nk.value for nk, _ in merged_list]:
                merged_list.append((k_node, v_node))
        return ruamel.yaml.nodes.MappingNode(
            tag="tag:yaml.org,2002:map", value=merged_list
        )

    # Main merging logic
    result_map = {}
    key_nodes = {}
    for key_node, val_node in nodes:
        k = key_node.value
        if k in result_map:
            existing_val = result_map[k]
            if (
                isinstance(existing_val, ruamel.yaml.nodes.MappingNode)
                and isinstance(val_node, ruamel.yaml.nodes.MappingNode)
            ):
                result_map[k] = merge_mapping_nodes(existing_val, val_node)
            else:
                result_map[k] = val_node  # last wins
        else:
            result_map[k] = val_node
            key_nodes[k] = key_node
    # Build the output list preserving insertion order
    out = [(key_nodes[k], result_map[k]) for k in result_map]
    return out

def deep_merge_nodes(nodes):
    """
    Merge duplicate mapping nodes inside a sequence of yaml nodes.
    """
    def merge_mapping_nodes(a_node, b_node):
        # Merge two MappingNode values recursively
        a_pairs = a_node.value
        b_pairs = b_node.value
        a_map = {k.value: k for (k, _) in a_pairs}
        b_map = {k.value: k for (k, _) in b_pairs}

        merged_pairs = []
        used_keys = set()

        for a_key_node, a_val_node in a_pairs:
            key = a_key_node.value
            if key in b_map:
                b_val_node = None
                # find the corresponding value in b_pairs
                for b_key_node, val in b_pairs:
                    if b_key_node.value == key:
                        b_val_node = val
                        break
                if isinstance(a_val_node, type(b_node)) and isinstance(b_val_node, type(b_node)):
                    # both MappingNode, merge recursively
                    merged_val = merge_mapping_nodes(a_val_node, b_val_node)
                    merged_pairs.append((a_key_node, merged_val))
                else:
                    # non-mapping values: last wins
                    merged_pairs.append((a_key_node, b_val_node))
                used_keys.add(key)
            else:
                merged_pairs.append((a_key_node, a_val_node))

        # Append any remaining keys from b that weren't in a
        for b_key_node, b_val_node in b_pairs:
            key = b_key_node.value
            if key not in used_keys:
                merged_pairs.append((b_key_node, b_val_node))

        return type(a_node)(tag=a_node.tag, value=merged_pairs)

    order = []
    cache = {}

    for key_node, val_node in nodes:
        key = key_node.value
        if key in cache:
            existing_key_node, existing_val_node = cache[key]
            if isinstance(existing_val_node, type(val_node)) and isinstance(val_node, type(val_node)):
                merged_val = merge_mapping_nodes(existing_val_node, val_node)
                cache[key] = (existing_key_node, merged_val)
            else:
                # non-mapping values: last wins
                cache[key] = (existing_key_node, val_node)
        else:
            cache[key] = (key_node, val_node)
            order.append(key)

    return [(cache[k][0], cache[k][1]) for k in order]

