    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    from collections import defaultdict
    summed = defaultdict(int)
    for d in dicts:
        for key, value in d.items():
            summed[key] += value
    return dict(summed)

