def _replace_url_args(url, url_args):
    import re
    # Replace placeholders of the form <key> or {key} with values from url_args
    pattern = re.compile(r'<(?P<k1>\w+)>|{(?P<k2>\w+)}')
    def repl(m):
        key = m.group('k1') or m.group('k2')
        if key not in url_args:
            raise KeyError(f"URL placeholder {key!r} not provided")
        return str(url_args[key])
    return pattern.sub(repl, url)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url_args or not isinstance(url, str):
        return url
    import re, urllib.parse
    # Patterns: {key}, :key, <key>
    pattern = re.compile(r'({(?P</S>[a-zA-Z0-9_-]+)}|:(?P</S>[a-zA-Z0-9_-]+)|<(?P</S>[a-zA-Z0-9_-]+)>)')
    def repl(match):
        key = match.group(1) or match.group(2) or match.group(3)
        if key in url_args:
            val = url_args[key]
            if isinstance(val, (list, tuple)):
                # join list items with commas
                val = ','.join(map(str, val))
            return urllib.parse.quote_plus(str(val))
        return match.group(0)
    return pattern.sub(repl, url)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    import re
    # Match patterns like {name}, <name> or :name
    pattern = re.compile(r'\{(?P<name>\w+)\}|\<(?P<name>\w+)\>|\:(?P<name>\w+)')
    def _repl(match):
        key = match.group('name')
        if key not in url_args:
            raise KeyError(f"URL argument '{key}' is missing")
        return str(url_args[key])
    return pattern.sub(_repl, url)

