def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    base = len(alphabet)
    if number < 0:
        return '-' + int_to_string(-number, alphabet, padding)
    digits = []
    if number == 0:
        digits.append(alphabet[0])
    else:
        while number:
            digits.append(alphabet[number % base])
            number //= base
    result = ''.join(reversed(digits))
    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result
    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("Negative numbers are not supported")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two symbols")
    if number == 0:
        result = [alphabet[0]]
    else:
        result = []
        while number:
            number, rem = divmod(number, base)
            result.append(alphabet[rem])
        result.reverse()
    if padding is not None and len(result) < padding:
        result = [alphabet[0]] * (padding - len(result)) + result
    return ''.join(result)

def _replace_register(flow_params, register_number, register_value):
    """
    Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    """
    def _recurse(obj):
        if isinstance(obj, dict):
            # Create a list of keys that need to be replaced
            keys_to_swap = [k for k in obj if k == register_value]
            for old_key in keys_to_swap:
                # Get the associated value and recurse on it
                val = obj.pop(old_key)
                obj[register_number] = _recurse(val)
            # Recurse on all remaining values
            for k, v in obj.items():
                obj[k] = _recurse(v)
        elif isinstance(obj, list):
            for i in range(len(obj)):
                obj[i] = _recurse(obj[i])
        elif isinstance(obj, tuple):
            return tuple(_recurse(v) for v in obj)
        else:
            # Replace any leaf value that matches the placeholder
            if obj == register_value:
                return register_number
        return obj

    return _recurse(flow_params)

