def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys
    import shlex
    # Auto-detect platform if requested
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1
    # Use shlex with appropriate positiveness
    if platform == 1:          # POSIX
        return shlex.split(s, posix=True)
    elif platform == 0:        # Windows/CMD
        return shlex.split(s, posix=False)
    else:
        raise ValueError(f"Unsupported platform value: {platform}")

def split(s, platform='this'):
    import sys, shlex, re
    # Resolve platform: 1 = POSIX, 0 = Windows/CMD
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1
    if platform == 1:
        # Use shlex for POSIX-like behaviour
        return shlex.split(s, posix=True)
    else:
        # Windows/CMD style parsing
        # Split on whitespace not inside double quotes, preserving quoted substrings
        pattern = r'(?:"([^"]*)"|(\S+))'
        tokens = []
        for quoted, plain in re.findall(pattern, s):
            if quoted:
                tokens.append(quoted)
            else:
                tokens.append(plain)
        return tokens

