def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or str(frequency).strip().lower() == "always":
        return None

    parts = str(frequency).strip().lower().split()
    if len(parts) != 2:
        raise ValueError(f"Cannot parse frequency: {frequency!r}")

    number_str, unit = parts
    try:
        value = int(number_str)
    except ValueError:
        raise ValueError(f"Frequency number must be an integer: {number_str!r}")

    if unit in ("second", "seconds"):
        return datetime.timedelta(seconds=value)
    if unit in ("minute", "minutes"):
        return datetime.timedelta(minutes=value)
    if unit in ("hour", "hours"):
        return datetime.timedelta(hours=value)
    if unit in ("day", "days"):
        return datetime.timedelta(days=value)
    if unit in ("week", "weeks"):
        return datetime.timedelta(weeks=value)
    if unit in ("month", "months"):
        return datetime.timedelta(days=30 * value)
    if unit in ("year", "years"):
        return datetime.timedelta(days=365 * value)

    raise ValueError(f"Unsupported time unit in frequency: {unit!r}")

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq_str = frequency.strip()
    if not freq_str:
        return None
    if freq_str.lower() == "always":
        return None
    import re
    pattern = r'^\s*(?P<value>\d+(\.\d+)?)\s*(?P<unit>\w+)\s*$'
    match = re.match(pattern, freq_str, re.IGNORECASE)
    if not match:
        raise ValueError(f"Invalid frequency format: '{frequency}'")
    value_str = match.group('value')
    try:
        val = float(value_str)
    except ValueError:
        raise ValueError(f"Invalid number in frequency: '{value_str}'")
    if not val.is_integer():
        raise ValueError(f"Fractional values not supported in frequency: '{frequency}'")
    val = int(val)
    unit = match.group('unit').lower()
    unit_map = {
        'day': 'days', 'days': 'days',
        'week': 'weeks', 'weeks': 'weeks',
        'hour': 'hours', 'hours': 'hours',
        'minute': 'minutes', 'minutes': 'minutes',
        'second': 'seconds', 'seconds': 'seconds',
        'microsecond': 'microseconds', 'microseconds': 'microseconds',
    }
    if unit not in unit_map:
        raise ValueError(f"Unknown time unit in frequency: '{unit}'")
    kwargs = {unit_map[unit]: val}
    return datetime.timedelta(**kwargs))

def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None:
        return None
    freq = frequency.strip()
    if not freq or freq.lower() == "always":
        return None

    parts = freq.split()
    if len(parts) < 2:
        raise ValueError(f"Could not parse frequency: {frequency}")

    try:
        amount = float(parts[0])
    except ValueError:
        raise ValueError(f"Invalid numeric value in frequency: {frequency}")

    unit = parts[1].lower()
    unit_map = {
        "day":    {"days": amount},
        "days":   {"days": amount},
        "week":   {"weeks": amount},
        "weeks":  {"weeks": amount},
        "hour":   {"hours": amount},
        "hours":  {"hours": amount},
        "minute": {"minutes": amount},
        "minutes":{"minutes": amount},
        "second": {"seconds": amount},
        "seconds":{"seconds": amount}
    }

    if unit not in unit_map:
        raise ValueError(f"Unrecognized time unit in frequency: {frequency}")

    return datetime.timedelta(**unit_map[unit])

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        host = host.strip()
    except Exception:
        return False
    if not host:
        return False

    # Common localhost identifiers
    if host.lower() == "localhost":
        return True
    if host == "127.0.0.1":
        return True
    if host == "::1":
        return True

    # Resolve the provided host to IP addresses
    try:
        host_ips = {addr[4][0] for addr in socket.getaddrinfo(host, None)}
    except socket.gaierror:
        return False

    # Resolve the local machine to IP addresses
    try:
        local_hostname = socket.gethostname()
    except Exception:
        local_hostname = None

    local_ips = set()
    if local_hostname:
        try:
            local_ips.update({addr[4][0] for addr in socket.getaddrinfo(local_hostname, None)})
        except socket.gaierror:
            pass

    # If any of the resolved host IPs match any local IP, consider it local
    if host_ips & local_ips:
        return True

    # Finally, check if the host string matches the local hostname (case-insensitive)
    if local_hostname and host.lower() == local_hostname.lower():
        return True

    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    # Check common literals first
    if host in {"localhost", "127.0.0.1", "::1"}:
        return True

    try:
        # Resolve the host to IP addresses (IPv4/IPv6)
        # getaddrinfo may return multiple results, we just need to check any
        for res in socket.getaddrinfo(host, None, socket.AF_UNSPEC, socket.SOCK_STREAM):
            family, _, _, _, sockaddr = res
            if family == socket.AF_INET:
                addr = sockaddr[0]
                if addr == "127.0.0.1":
                    return True
            elif family == socket.AF_INET6:
                addr = sockaddr[0]
                if addr in ("::1", "0:0:0:0:0:0:0:1"):
                    return True
    except socket.gaierror:
        # Host could not be resolved; not local
        return False

    return False

def is_local(host):
    """
    Checks if the host is the localhost.

    :param host: The hostname or IP address to check.
    :return: True if the host resolves to a local loopback address.
    """
    try:
        # Resolve the host to its addresses
        addrinfo = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False

    for res in addrinfo:
        family, _, _, _, sockaddr = res
        if family == socket.AF_INET:
            ip = sockaddr[0]
            # IPv4 loopback addresses are 127.0.0.0/8
            if ip.startswith("127."):
                return True
        elif family == socket.AF_INET6:
            ip = sockaddr[0]
            # IPv6 loopback is ::1
            if ip == "::1":
                return True
    return False

def is_local(host):
