    except socket.gaierror:
        # Possibly an IPv6 address or unresolvable host; fall back to IPv6 resolution below
        pass

    # Try IPv6 resolution
    try:
        addr_info = socket.getaddrinfo(h, None, socket.AF_INET6)
        for entry in addr_info:
            addr = entry[4][0]
