    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    # On normal Windows the os.name is 'nt'; Git Bash provides a POSIX-like environment
    if os.name != 'posix':
        return False

    # Try to use os.uname() which is available in MSYS/MinGW
    try:
        uname = os.uname()
        # Git Bash sets sysname to 'Windows' and OSTYPE to 'msys'
        if 'Windows' in uname.sysname:
            if os.environ.get('OSTYPE', '').startswith('msys'):
                return True
            # Alternative check for MINGW identifiers
            if os.environ.get('MSYSTEM', '').lower().startswith('mingw'):
                return True
    except AttributeError:
        # os.uname may not be available
        pass

    return False

