        try:
            var_name = matcher.group(1)
            try:
                default_val = matcher.group(2)
            except Exception:
                default_val = None
            groups = {"var": var_name, "default": default_val}
        except Exception:
            # Unable to interpret matcher
            raise ValueError("Matcher format not recognized; expected a regex match or similar object with group information.")
    # Determine the variable name from known keys
    var_name = None
    for key in ("var", "name", "key", "variable"):
        if key in groups:
            var_name = groups[key]
            break
    if var_name is None:
        raise ValueError("No variable name found in matcher.")
    # Get default value if provided
    default_val = groups.get("default")
    # Resolve from environment
    if var_name in os.environ:
        return os.environ[var_name]
    if default_val is not None:
        return default_val
    raise KeyError(f"Environment variable '{var_name}' is not set and no default value provided.")

