def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    if isinstance(commands, str):
        commands = [commands]
    if args is None:
        args = []
    elif not isinstance(args, (list, tuple)):
        args = [args]
    results = []
    for cmd in commands:
        cmd_list = [cmd] + args
        if verbose:
            print("Running command:", " ".join(cmd_list))
        try:
            proc = subprocess.run(
                cmd_list,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
                text=True,
                check=False
            )
            results.append(proc)
        except Exception as exc:
            if verbose:
                print(f"Command {cmd} failed with exception: {exc}")
            results.append(None)
    return results

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    if isinstance(commands, (list, tuple)):
        cmd = list(commands)
    else:
        cmd = [commands]
    if args:
        if isinstance(args, (list, tuple)):
            cmd.extend(args)
        else:
            cmd.append(args)
    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=False
        )
        stdout = result.stdout
        stderr = result.stderr
        if verbose:
            print(f"Command: {' '.join(cmd)}")
            if stdout:
                print(f"---stdout---\n{stdout}")
            if not hide_stderr and stderr:
                print(f"---stderr---\n{stderr}")
        return stdout, stderr, result.returncode
    except Exception as exc:
        err_msg = str(exc)
        if verbose:
            print(f"Error running command: {err_msg}")
        return "", err_msg, -1

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, (str, bytes)):
        cmd = [commands] + list(args or [])
    else:
        cmd = list(commands) + list(args or [])
    try:
        result = subprocess.run(cmd, cwd=cwd, env=env, capture_output=True, text=True)
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {cmd[0]}") from e
    if verbose:
        if result.stdout:
            print(result.stdout, end='')
        if not hide_stderr and result.stderr:
            print(result.stderr, end='')
    return result

