def gaussian(x):
    """Gaussian centered around 0.2 with a sigma of 0.1."""
    mu = 0.2
    sigma = 0.1
    return np.exp(-0.5 * ((x - mu) / sigma)**2) / (sigma * np.sqrt(2 * np.pi))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import os
    import logging
    import json
    import sys

    try:
        import yaml
    except ImportError:
        yaml = None

    configs = {}
    error_records = []

    logger = logging.getLogger('config_loader')

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as fh:
                if filename.lower().endswith(('.yaml', '.yml')):
                    if yaml is None:
                        raise ImportError("PyYAML is required for YAML configuration files")
                    data = yaml.safe_load(fh)
                else:
                    data = json.load(fh)
        except Exception as exc:
            exc_info = sys.exc_info()
            record = logger.makeRecord(
                name='config_loader',
                level=logging.ERROR,
                fn=filename,
                lno=0,
                msg=f"Failed to load configuration {filename}: {exc}",
                args=(),
                exc_info=exc_info
            )
            error_records.append(record)
            continue

        if resolve_env and isinstance(data, (dict, list, str)):
            def _resolve_env(obj):
                if isinstance(obj, str):
                    return os.path.expandvars(obj)
                if isinstance(obj, dict):
                    return {k: _resolve_env(v) for k, v in obj.items()}
                if isinstance(obj, list):
                    return [_resolve_env(item) for item in obj]
                return obj

            data = _resolve_env(data)

        if overrides and isinstance(data, dict):
            for key, value in overrides.items():
                data[key] = value

        configs[filename] = data

    return configs, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    logger = logging.getLogger('config_loader')
    configurations = {}
    errors = []

    # Helper to resolve environment variables in strings
    def _resolve_env(value):
        import re
        env_pattern = re.compile(r'\${([^}]+)}')
        if isinstance(value, str):
            return env_pattern.sub(lambda m: os.environ.get(m.group(1), m.group(0)), value)
        elif isinstance(value, dict):
            return {_resolve_env(k): _resolve_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env(v) for v in value]
        else:
            return value

    # Helper to merge overrides (shallow)
    def _apply_overrides(cfg, overrides_dict):
        if overrides_dict and isinstance(overrides_dict, dict):
            for k, v in overrides_dict.items():
                cfg[k] = v
        return cfg

    # Load JSON module
    try:
        json = __import__('json')
    except ImportError:
        json = None

    # Load YAML module if available
    try:
        yaml = __import__('yaml')
    except ImportError:
        yaml = None

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                contents = f.read()
        except Exception as e:
            records = logger.makeRecord(
                'config_loader', logging.ERROR, fname, 0,
                'Failed to read file {}: {}'.format(fname, e), None, exc_info=True)
            errors.append(records)
            continue

        # Determine parser
        try:
            if fname.endswith('.json') and json is not None:
                parsed = json.loads(contents)
            elif (fname.endswith('.yaml') or fname.endswith('.yml')) and yaml is not None:
                parsed = yaml.safe_load(contents)
            else:
                # Default to JSON if possible
                if json is not None:
                    parsed = json.loads(contents)
                else:
                    raise ValueError('Unsupported file type and no JSON parser available')
        except Exception as e:
            records = logger.makeRecord(
                'config_loader', logging.ERROR, fname, 0,
                'Failed to parse file {}: {}'.format(fname, e), None, exc_info=True)
            errors.append(records)
            continue

        if not isinstance(parsed, dict):
            records = logger.makeRecord(
                'config_loader', logging.ERROR, fname, 0,
                'Parsed configuration from {} is not a dictionary'.format(fname), None, exc_info=None)
            errors.append(records)
            continue

        # Apply overrides
        parsed = _apply_overrides(parsed, overrides)

        # Resolve environment variables
        if resolve_env:
            parsed = _resolve_env(parsed)

        configurations[fname] = parsed

    return configurations, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Load a sequence of configuration files and validate each one.
    Returns a tuple:
        (dict mapping filename -> parsed configuration, list of LogRecord objects for errors)
    """
    import os
    import json
    import logging

    def _merge_with_overrides(target, overrides_dict):
        """Recursively merge override dictionary into target dictionary."""
        for key, value in overrides_dict.items():
            if (
                isinstance(value, dict)
                and isinstance(target.get(key), dict)
            ):
                _merge_with_overrides(target[key], value)
            else:
                target[key] = value

    def _expand_env_vars(obj):
        """Recursively expand environment variables in strings within the configuration object."""
        if isinstance(obj, dict):
            return {
                k: _expand_env_vars(v)
                for k, v in obj.items()
            }
        elif isinstance(obj, list):
            return [_expand_env_vars(item) for item in obj]
        elif isinstance(obj, str):
            return os.path.expandvars(obj)
        else:
            return obj

    configurations = {}
    error_records = []

    for filename in config_filenames:
        try:
            with open(filename, "r", encoding="utf-8") as f:
                file_content = f.read()

            # Try YAML first
            try:
                import yaml

                parsed = yaml.safe_load(file_content)
            except Exception:
                # Fall back to JSON
                try:
                    parsed = json.loads(file_content)
                except json.JSONDecodeError as json_err:
                    raise json_err

            if parsed is None:
                parsed = {}

            # Apply overrides if provided
            if overrides:
                if not isinstance(parsed, dict):
                    raise TypeError(
                        f"Configuration from {filename} is not a dictionary and cannot be overridden."
                    )
                if not isinstance(overrides, dict):
                    raise TypeError("Overrides must be a dictionary.")
                _merge_with_overrides(parsed, overrides)

            # Resolve environment variables if requested
            if resolve_env:
                parsed = _expand_env_vars(parsed)

            configurations[filename] = parsed

        except Exception as exc:
            exc_info = (type(exc), exc, exc.__traceback__)
            msg = f"Failed to load configuration file '{filename}': {exc}"
            record = logging.LogRecord(
                name="config_loader",
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=msg,
                args=None,
                exc_info=exc_info,
            )
            error_records.append(record)

    return configurations, error_records

