def from_ticks(cls, ticks, tz=None):
    if not isinstance(ticks, int):
        raise TypeError("ticks must be an integer")
    # 86400 seconds * 10**9 ns = 86400000000000 ns (24 hours)
    if ticks < 0 or ticks >= 86400000000000:
        raise ValueError("ticks out of bounds: must be in [0, 86400000000000)")
    # split into whole seconds and remaining nanoseconds
    seconds, nanos = divmod(ticks, 1_000_000_000)
    hour, rem = divmod(seconds, 3600)
    minute, second = divmod(rem, 60)
    microsecond = nanos // 1000
    return cls(hour, minute, second, microsecond, tz=tz)

