def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        bookmarks = []
        for v in values:
            # If a Bookmark class with a from_raw method is available, use it.
            if hasattr(cls, "Bookmark") and hasattr(cls.Bookmark, "from_raw"):
                try:
                    bookmarks.append(cls.Bookmark.from_raw(v))
                    continue
                except Exception:
                    pass
            # Fall back to storing the raw string.
            bookmarks.append(v)
        return cls(bookmarks)

def from_raw_values(cls, values):
        """Create a Bookmarks object from an iterable of raw bookmark strings.

        Each raw value is expected to be a string (or bytes) that can be parsed
        into a :class:`Bookmark` via :class:`Bookmark.from_raw_value`.  Invalid
        entries are skipped silently.

        :param values: Iterable of raw bookmark representations.
        :type values: Iterable[str | bytes]
        :return: A new ``Bookmarks`` instance containing the parsed bookmarks.
        """
        bookmarks = []
        for raw in values:
            # Allow bytes input for convenience
            if isinstance(raw, bytes):
                try:
                    raw = raw.decode("utf-8")
                except Exception:
                    continue
            # Skip empty or whitespace-only strings
            if not raw or raw.isspace():
                continue
            # Delegate parsing to the Bookmark class; ignore failures
            try:
                bookmark = Bookmark.from_raw_value(raw)
            except Exception:
                continue
            bookmarks.append(bookmark)
        return cls(bookmarks)

