    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    # If the input is already a basic sequence type, return it unchanged.
    if isinstance(seq, (str, bytes, bytearray, list, tuple)):
        return seq, type(seq)

    # Attempt to materialize an iterable into a list.
    try:
        seq = list(seq)
    except Exception:
        # If the object cannot be iterated, leave it as is (could be a scalar or custom type).
        pass

    return seq, type(seq)

