    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    import numpy as np
    # If seq is already a NumPy array or scalar, return it (or wrap scalar).
    if isinstance(seq, np.ndarray):
        return seq, seq.dtype.type
    if isinstance(seq, np.generic):
        return np.array([seq]), type(seq)
    # Try to convert to an array; if seq is a scalar (non-iterable), wrap it.
    try:
        arr = np.array(seq, copy=False)
        if arr.ndim == 0:  # scalar
            arr = np.array([seq], copy=False)
        return arr, arr.dtype.type
    except Exception:
        # Not iterable – treat as a single-element sequence.
        return np.array([seq]), type(seq)

