    """
    Return a (sequence, type) pair.

    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Check for built‑in sequence types
    if (hasattr(seq, "__len__") and hasattr(seq, "__getitem__")) or isinstance(seq, (str, bytes, bytearray)):
        return seq, type(seq)

    # Try to obtain an iterator
    try:
        iterator = iter(seq)
    except TypeError:
        # Not iterable; treat as a singleton
        return [seq], type([seq])

    # Convert the iterator to a list, respecting *bufsize* if given
    if bufsize is not None:
        import itertools
        seq_list = list(itertools.islice(iterator, bufsize))
    else:
        seq_list = list(iterator)

    return seq_list, type(seq_list)

