    """Get or set the scale of the graph.

    If *other* is ``None``, return the current scale of this graph.
    If a numeric *other* is provided, all values and errors of the
    last coordinate field are multiplied by *other*.  The internal
    ``_scale`` value is adjusted accordingly.
    """
    # Get current scale
    if other is None:
        return getattr(self, "_scale", None)

    # Validate the new scale
    if not isinstance(other, (int, float)):
        raise TypeError("Scale value must be numeric")

    # The graph must have a defined, non‑zero scale to be rescaled
    current_scale = getattr(self, "_scale", None)
    if current_scale is None or current_scale == 0:
        raise LenaValueError("Cannot rescale graph with unknown or zero scale")

    # Rescale the last coordinate field and its error (if present)
    if not hasattr(self, "_fields") or not self._fields:
        raise LenaValueError("Graph has no fields to rescale")

    last_field = self._fields[-1]
    # Basic support for common containers: list, tuple, numpy.ndarray, pandas.Series, etc.
    try:
        # Multiply all numeric data points by the new scale factor
        # We modify in place to avoid allocations
        if hasattr(last_field, "values"):
            last_field.values = [v * other for v in last_field.values]
        else:
            # Fall back to standard attribute access
            last_field.value = [v * other for v in last_field.value] \
                if hasattr(last_field, "value") else None

        # Rescale errors if the field provides them
        if hasattr(last_field, "error"):
            if hasattr(last_field.error, "__iter__"):
                last_field.error = [e * other for e in last_field.error]
            else:
                last_field.error = last_field.error * other
    except Exception:
        # If the attribute layout is unexpected we silently skip
        pass

    # Update the graph's internal scale
    self._scale = current_scale * other
    return self

