    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.
    """
    from zope.interface.exceptions import Invalid
    import inspect

    errors = []

    # 1. check interface implementation claim
    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(
                Invalid(
                    f"{candidate!r} does not claim to provide {iface!r}"
                )
            )

    # 2. check required methods
    if hasattr(iface, "_required_methods"):
        for name in iface._required_methods:
            # Must exist
            method = getattr(candidate, name, None)
            if method is None:
                errors.append(
                    Invalid(
                        f"{candidate!r} does not define required method {name!r}"
                    )
                )
                continue
            # Must be callable
            if not callable(method):
                errors.append(
                    Invalid(
                        f"Attribute {name!r} of {candidate!r} must be callable"
                    )
                )
                continue
            # Signature check
            iface_dist = getattr(iface, name, None)
            if iface_dist is not None and hasattr(iface_dist, "signature"):
                iface_sig = iface_dist.signature
                try:
                    cand_sig = inspect.signature(method)
                except (ValueError, TypeError):
                    errors.append(
                        Invalid(
                            f"Unable to inspect signature of {name!r} in {candidate!r}"
                        )
                    )
                    continue
                # Simplified comparison: same number of parameters
                if len(cand_sig.parameters) != len(iface_sig.parameters):
                    errors.append(
                        Invalid(
                            f"Signature mismatch for {name!r} in {candidate!r}: "
                            f"expected {iface_sig}, got {cand_sig}"
                        )
                    )
