    def common_metaclass(m0, m1):
        """Return the most derived metaclass between m0 and m1."""
        if issubclass(m1, m0):
            return m1
        if issubclass(m0, m1):
            return m0
        # Find a common ancestor in m0's MRO that is a subclass of m1
        for cls in m0.__mro__:
            if issubclass(cls, m1):
