    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Ensure no trailing slash on the base URL
    base = url.rstrip('/')
    # Determine the NodeInfo endpoint path
    if document_path is None:
        document_path = '/nodeinfo/2.0'
    # Normalize leading slash
    if not document_path.startswith('/'):
        document_path = '/' + document_path
    href = base + document_path
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/name#nodeinfo",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json, xml.etree.ElementTree as ET

    result = {"subject": None, "aliases": [], "links": []}

    # Try JSON first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            result["subject"] = data.get("subject") or data.get("subject")
            result["aliases"] = data.get("aliases", [])
            for link in data.get("links", []):
                href = link.get("href")
                if href:  # only include if href exists
                    result["links"].append({
                        "rel": link.get("rel"),
                        "href": href,
                        "type": link.get("type")
                    })
            return result
    except json.JSONDecodeError:
        pass

    # Fall back to XRD (XML)
    try:
        root = ET.fromstring(document)
        # Resolve namespace if present
        ns_tag = root.tag[root.tag.find("{"):root.tag.find("}") + 1] if "}" in root.tag else ""
        for child in root:
            tag = child.tag.replace(ns_tag, "")
            if tag == "Subject":
                result["subject"] = child.text.strip() if child.text else None
            elif tag == "Alias":
                if child.text:
                    result["aliases"].append(child.text.strip())
            elif tag == "Link":
                href = child.attrib.get("href")
                if href:
                    result["links"].append({
                        "rel": child.attrib.get("rel"),
                        "href": href,
                        "type": child.attrib.get("type")
                    })
        return result
    except ET.ParseError:
        pass

    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse a Diaspora WebFinger document which may be in the new JSON format or the legacy XRD XML format.
    Returns a dictionary containing the parsed fields: subject, aliases, properties, and links.
    """
    import json
    import xml.etree.ElementTree as ET

    # Attempt to parse as JSON
    try:
        data = json.loads(document)
        # Construct a uniform dictionary
        result: Dict = {}
        result['subject'] = data.get('subject')
        result['aliases'] = data.get('alias', [])
        result['properties'] = data.get('properties', {})
        # Links are a list of dictionaries with at least 'rel' and 'href'
        result['links'] = data.get('links', [])
        return result
    except (json.JSONDecodeError, TypeError):
        pass  # Continue to try XML parsing

    # Attempt to parse as XRD XML
    try:
        root = ET.fromstring(document)
        ns_map = {}
        if root.tag.startswith('{'):
            uri, _ = root.tag[1:].split('}')
            ns_map['xrd'] = uri

        # Helper to find elements with or without namespace
        def find(elem, tag, default=None):
            return (root.find(f'.//{{*}}{tag}') or root.find(f'.//{tag}') or default)

        def findall(elem, tag):
            return (root.findall(f'.//{{*}}{tag}') + root.findall(f'.//{tag}'))

        result: Dict = {}

        subject_elem = find(root, 'Subject')
        if subject_elem is not None and subject_elem.text:
            result['subject'] = subject_elem.text

        # Aliases
        aliases = [a.text for a in findall(root, 'Alias') if a.text]
        result['aliases'] = aliases

        # Properties (name attributes)
        props = {}
        for prop in findall(root, 'Property'):
            name = prop.attrib.get('name')
            if name and prop.text:
                props[name] = prop.text
        result['properties'] = props

        # Links
        links = []
        for link in findall(root, 'Link'):
            link_dict = {k: v for k, v in link.attrib.items()}
            if link.text:
                link_dict['text'] = link.text
            links.append(link_dict)
        result['links'] = links

        return result
    except Exception:
        # If parsing fails, return an empty dict
        return {}

def parse_diaspora_webfinger(document: str) -> dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Try JSON first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            return data
    except Exception:
        pass

    # Fallback: try XML (XRD)
    try:
        root = ET.fromstring(document)
    except ET.ParseError as e:
        raise ValueError(f"Unable to parse webfinger document as JSON or XML: {e}")

    # Namespaces that might appear in the XRD document
    ns = {
        'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0',
        'xrd2': 'http://docs.oasis-open.org/ns/xri/xrd-2.0',
    }

    # Helper to find element with optional namespace
    def _find(element, tag, namespaces=None):
        if namespaces:
            for prefix, uri in namespaces.items():
                found = element.find(f'{{{uri}}}{tag}')
                if found is not None:
                    return found
        return element.find(tag)

    def _findall(element, tag, namespaces=None):
        matches = []
        if namespaces:
            for prefix, uri in namespaces.items():
                matches.extend(element.findall(f'{{{uri}}}{tag}'))
        matches.extend(element.findall(tag))
        return matches

    # Locate the XRD container element
    xrd_elem = _find(root, 'XRD', ns)
    if xrd_elem is None:
        # Sometimes the root itself is the XRD element
        if root.tag.endswith('XRD'):
            xrd_elem = root

    if xrd_elem is None:
        raise ValueError("Could not find XRD element in the document")

    # Parse subject
    subject_elem = _find(xrd_elem, 'Subject', ns)
    subject = subject_elem.text.strip() if subject_elem is not None and subject_elem.text else None

    # Parse aliases
    alias_elems = _findall(xrd_elem, 'Alias', ns)
    aliases = [ae.text.strip() for ae in alias_elems if ae.text]

    # Parse links
    link_elems = _findall(xrd_elem, 'Link', ns)
    links = []
    for le in link_elems:
        link_attrs = {}
        # Preserve all attributes
        for attr in le.attrib:
            link_attrs[attr] = le.attrib[attr]
        # Additionally, if the tag has text content, treat it as href if not already set
        if 'href' not in le.attrib and le.text and le.text.strip():
            link_attrs['href'] = le.text.strip()
        links.append(link_attrs)

    result = {
        'subject': subject,
        'aliases': aliases,
        'links': links,
    }
    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Try JSON first
    try:
        data = json.loads(document)
        # The new format is already a dict; ensure it has the expected keys.
        if isinstance(data, dict):
            # Normalize keys if necessary
            return{
                "subject": data.get("subject"),
                "aliases": data.get("aliases", []),
                "links": data.get("links", [])
            }
    except json.JSONDecodeError:
        pass

    # Assume XRD (XML) if JSON parsing failed
    try:
        root = ET.fromstring(document)
    except ET.ParseError:
        return {"error": "Invalid webfinger document"}

    def _localname(tag):
        return tag.split("}", 1)[-1] if "}" in tag else tag

    subject = None
    aliases = []
    links = []

    for elem in root.iter():
        name = _localname(elem.tag)
        if name == "Subject" and subject is None:
            subject = elem.text
        elif name == "Alias":
            if elem.text:
                aliases.append(elem.text)

    for link_elem in [e for e in root.iter() if _localname(e.tag) == "Link"]:
        link = {}
        for attr, val in link_elem.attrib.items():
            link[_localname(attr)] = val
        for child in link_elem:
            lname = _localname(child.tag)
            if child.text:
                link[lname] = child.text
            else:
                # If the child has sub-elements, store them as a dict
                sub = {}
                for sub_child in child:
                    sub[_localname(sub_child.tag)] = sub_child.text
                if sub:
                    link[lname] = sub
        links.append(link)

    return {
        "subject": subject,
        "aliases": aliases,
        "links": links
    }

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        if '@' not in handle:
            return None
        username, domain = handle.split('@', 1)
        # RFC7033 requires the resource to be URL‑encoded
        import urllib.parse
        resource = urllib.parse.quote(f'acct:{handle}', safe='')
        url = f'https://{domain}/.well-known/webfinger?resource={resource}'
        import urllib.request
        req = urllib.request.Request(
            url,
            headers={
                'Accept': 'application/jrd+json, application/json',
                'User-Agent': 'webfinger-client/1.0',
            },
        )
        with urllib.request.urlopen(req, timeout=10) as resp:
            if resp.status == 200:
                # Determine charset; default to utf-8 if unknown
                charset = resp.headers.get_content_charset('utf-8')
                return resp.read().decode(charset)
    except Exception:
        # Any network or parsing issue results in None, no exception raised
        return None
    return None

