def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import urllib.request
    import urllib.parse
    import json
    from urllib.error import URLError, HTTPError

    if not handle:
        raise ValueError("handle must be provided")

    # Ensure handle is in the form local_user@domain
    if handle.startswith("acct:"):
        # The caller may have already provided the acct URI
        acct_uri = handle
        try:
            local_part, domain = handle.split("acct:", 1)[1].split("@", 1)
        except ValueError:
            raise ValueError("handle must contain '@' after optional 'acct:' prefix")
    else:
        acct_uri = f"acct:{handle}"
        try:
            local_part, domain = handle.split("@", 1)
        except ValueError:
            raise ValueError("handle must be of the form local_user@domain")

    # Construct the webfinger URL
    query = urllib.parse.urlencode({"resource": acct_uri})
    url = f"https://{domain}/.well-known/webfinger?{query}"

    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            if response.status != 200:
                raise RuntimeError(f"HTTP error {response.status} while fetching webfinger")
            raw_data = response.read().decode("utf-8")
    except HTTPError as err:
        raise RuntimeError(f"HTTPError while fetching webfinger: {err.code} {err.reason}") from err
    except URLError as err:
        raise RuntimeError(f"URLError while fetching webfinger: {err.reason}") from err

    try:
        data = json.loads(raw_data)
    except json.JSONDecodeError as err:
        raise ValueError(f"Failed to parse JSON from webfinger: {err.msg}") from err

    return data

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve (e.g., "user@pod.example.com")
    :returns: dict
    """
    import requests
    from requests.exceptions import RequestException, HTTPError, SSLError

    if not handle or '@' not in handle:
        raise ValueError("Invalid handle: must be in the form 'user@pod.com'")

    local, host = handle.split('@', 1)
    resource = f"acct:{local}@{host}"
    webfinger_path = f"/.well-known/webfinger?resource={resource}"
    https_url = f"https://{host}{webfinger_path}"
    http_url = f"http://{host}{webfinger_path}"
    headers = {"Accept": "application/jrd+json"}

    def _fetch(url):
        try:
            resp = requests.get(url, timeout=5, headers=headers)
            resp.raise_for_status()
            return resp.json()
        except HTTPError as e:
            raise ValueError(f"HTTP error while retrieving webfinger for {handle}: {e}") from e
        except (SSLError, RequestException) as e:
            # SSL or general connection errors; let caller retry with alternate scheme
            raise e

    # Try HTTPS first, fall back to HTTP if SSL error occurs
    try:
        return _fetch(https_url)
    except SSLError:
        # Attempt HTTP without raising SSL exception
        try:
            return _fetch(http_url)
        except (RequestException, HTTPError) as e:
            raise ValueError(f"Failed to retrieve webfinger for {handle} with both HTTPS and HTTP: {e}") from e
    except RequestException as e:
        # Some other request exception, try HTTP fallback
        try:
            return _fetch(http_url)
        except (RequestException, HTTPError) as e2:
            raise ValueError(f"Failed to retrieve webfinger for {handle} with both HTTPS and HTTP: {e2}") from e2
    except Exception as e:
        raise ValueError(f"Unexpected error retrieving webfinger for {handle}: {e}") from e

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document and return it as an XRD instance.

    :arg host: Host to retrieve from (e.g. "example.com")
    :returns: XRD instance parsed from the host-meta XML
    :raises Exception: if the document cannot be retrieved or parsed
    """
    import requests

    # Construct the well-known host-meta URLs (try HTTPS first, then HTTP)
    urls = [f"https://{host}/.well-known/host-meta", f"http://{host}/.well-known/host-meta"]

    headers = {"Accept": "application/xrd+xml"}

    for url in urls:
        try:
            response = requests.get(url, timeout=10, headers=headers)
            if response.status_code == 200:
                try:
                    # Parse the returned XML into an XRD instance
                    return XRD.from_string(response.text)
                except Exception as exc:
                    raise ValueError(f"Failed to parse host-meta from {url}: {exc}") from exc
            elif response.status_code == 404:
                # If 404, try the next URL
                continue
            else:
                raise ValueError(f"Unexpected status code {response.status_code} when accessing {url}")
        except requests.RequestException as exc:
            # Continue to next URL on network-related errors
            continue

    raise ValueError(f"Could not retrieve a valid host-meta document from any of the hosts for {host}")

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """
    Helper method to send a document via HTTP.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests``.
    """
    import requests
    # Resolve the method function
    try:
        request_func = getattr(requests, method.lower())
    except AttributeError:
        # Unsupported HTTP method
        return None, ValueError(f"Unsupported method '{method}'")

    try:
        # Send the request
        response = request_func(url, data=data, timeout=timeout, *args, **kwargs)
        return response.status_code, None
    except requests.exceptions.RequestException as exc:
        # Return None for status and the exception instance that was raised
        return None, exc

