    files = []

    # Normalize spec_option to a list of glob patterns
    if spec_option is None:
        patterns = []
    elif isinstance(spec_option, (list, tuple)):
        patterns = list(spec_option)
    else:
        patterns = [spec_option]

    for dir_path in settings_dirs:
        path = Path(dir_path)
        if not path.is_dir():
            continue

        if patterns:
            for pat in patterns:
                for p in path.rglob(pat):
                    if p.is_file():
                        files.append(p)
        else:
            for p in path.iterdir():
                if p.is_file():
                    files.append(p)

