def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    if not isinstance(parser_dict, dict):
        raise ValueError("parser_dict must be a dict")

    # If there's no include directive, just return the original dict
    if "include" not in parser_dict:
        return parser_dict

    # Extract and remove the include directive
    include = parser_dict.pop("include")

    # Normalise the include structure to a list of dictionaries
    if isinstance(include, dict):
        include_items = [include]
    elif isinstance(include, (list, tuple)):
        include_items = include
    else:
        # If include is a single key, wrap it in a dict for processing
        include_items = [{include: None}]

    # Resolve each include entry
    for inc in include_items:
        # An include entry can be a dict mapping group names to data
        if isinstance(inc, dict):
            for key, val in inc.items():
                if val is None:
                    continue
                # If the value is a dictionary, merge recursively
                if isinstance(val, dict):
                    # Ensure the target key exists as a dict
                    target = parser_dict.setdefault(key, {})
                    if not isinstance(target, dict):
                        # Cannot merge a non-dict; replace it
                        target = {}
                        parser_dict[key] = target
                    # Recursively resolve includes in the included data
                    target.update(self._include_groups(val))
                else:
                    # For non-dict values, just set/overwrite
                    parser_dict[key] = val
        else:
            # An include entry is a single key referencing a group
            # Attempt to load this group from the environment/registry
            group_data = getattr(self, "_group_registry", {}).get(inc)
            if group_data is not None:
                parser_dict.update(self._include_groups(group_data))
            else:
                # If the group is not found, raise an error
                raise KeyError(f"Included group '{inc}' not found in registry")

    return parser_dict

def _include_groups(self, parser_dict):
    """
    Resolves the include dict directive in the spec files by recursively loading
    referenced YAML/JSON files and merging their contents into the current
    specification dictionary.
    """
    import os
    import yaml

    seen_files = set()

    def _load_file(filepath):
        # Avoid circular includes
        real_path = os.path.realpath(filepath)
        if real_path in seen_files:
            return {}
        seen_files.add(real_path)
        with open(real_path, 'r', encoding='utf-8') as f:
            # Load as YAML – will also parse valid JSON
            return yaml.safe_load(f) or {}

    def _resolve(node, base_dir):
        if isinstance(node, dict):
            resolved = {}
            for key, value in node.items():
                # Detect include directive – can be a dict with a special key
                if isinstance(value, dict) and ('$include' in value or 'include' in value):
                    include_path = None
                    if '$include' in value:
                        include_path = value['$include']
                    else:
                        include_path = value['include']

                    # Resolve relative paths
                    if not os.path.isabs(include_path):
                        include_path = os.path.normpath(os.path.join(base_dir, include_path))

                    included = _load_file(include_path)
                    # Recursively resolve the included content
                    included_resolved = _resolve(included, os.path.dirname(include_path))
                    # Merge included content into the current dict
                    resolved.update(included_resolved)
                else:
                    resolved[key] = _resolve(value, base_dir)
            return resolved
        elif isinstance(node, list):
            return [_resolve(item, base_dir) for item in node]
        else:
            return node

    # Determine the base directory for relative includes.
    # Prefer a stored attribute if the class provides it; otherwise use cwd.
    base_dir = getattr(self, 'base_dir', os.getcwd())
    return _resolve(parser_dict, base_dir)

def _include_groups(self, parser_dict):
        """
        Recursively resolve include directives in a parsed spec dictionary.
        The method looks for keys whose value is a dictionary containing
        an 'include' directive. The directive can be either a string
        path or a mapping with keys 'file', 'path', and optional 'keys'
        to restrict what parts of the included file are merged.
        """
        import yaml, os

        def _resolve(obj, base_path=None):
            if isinstance(obj, dict):
                # Work on a copy of the keys to avoid issues when modifying dict during iteration
                for key in list(obj.keys()):
                    val = obj[key]
                    if isinstance(val, dict) and 'include' in val:
                        inc = val['include']
                        # Resolve include path
                        if isinstance(inc, str):
                            inc_path = inc
                        elif isinstance(inc, dict):
                            inc_path = inc.get('file') or inc.get('path')
                        else:
                            continue

                        # Resolve relative to base path
                        if base_path:
                            inc_path = os.path.join(base_path, inc_path)

                        try:
                            with open(inc_path, 'r') as fh:
                                inc_content = yaml.safe_load(fh)
                        except Exception:
                            # If file cannot be read, skip inclusion
                            continue

                        # If inc directive specifies a list of keys to include
                        if isinstance(inc, dict) and 'keys' in inc:
                            keys = inc['keys']
                            if isinstance(keys, list) and isinstance(inc_content, dict):
                                inc_content = {k: inc_content.get(k) for k in keys if k in inc_content}

                        # Recursively resolve nested includes in the included content
                        inc_content = _resolve(inc_content, os.path.dirname(inc_path))
                        obj[key] = inc_content
                    else:
                        # Recurse into nested structures
                        obj[key] = _resolve(val, base_path)
                return obj
            elif isinstance(obj, list):
                return [_resolve(item, base_path) for item in obj]
            else:
                return obj

        # Determine base path from nearest file location if possible
        base_dir = getattr(self, '_base_dir', None)
        return _resolve(parser_dict, base_dir)

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    spec = getattr(self, "spec", None)
    if spec is None:
        return defaults

    # The spec might expose arguments as .arguments or .args
    args_container = getattr(spec, "arguments", getattr(spec, "args", None))
    if args_container is None:
        return defaults

    # Try to iterate over dictionary items; fall back to a plain iterable
    try:
        items = args_container.items()
    except AttributeError:
        items = args_container

    for key, value in items:
        # If an argument is defined as a mapping, pull 'default' if present
        if isinstance(value, dict):
            if "default" in value:
                defaults[key] = value["default"]
        else:
            # If the value itself is the default
            defaults[key] = value

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Resolve defaults defined in the specification
    spec = getattr(self, "spec", None)
    if spec:
        if isinstance(spec, dict):
            # spec may contain an 'args' list
            for arg in spec.get("args", []):
                if isinstance(arg, dict) and "name" in arg:
                    name = arg["name"]
                    if "default" in arg:
                        defaults[name] = arg["default"]
                else:
                    # fall back to object attributes
                    name = getattr(arg, "name", None)
                    if name and hasattr(arg, "default"):
                        defaults[name] = getattr(arg, "default")
        else:
            # if spec is an object, use its annotations or attributes
            annotations = getattr(spec, "__annotations__", {})
            for name in annotations:
                # prefer attribute if set
                if hasattr(spec, name):
                    defaults[name] = getattr(spec, name)
    # Merge values from other sources (e.g., environment, config)
    other = getattr(self, "other_sources", {})
    if isinstance(other, dict):
        for key, value in other.items():
            if key not in defaults:
                defaults[key] = value
    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # `spec` is assumed to be a mapping of argument names to a spec dict,
    # where each spec dict may contain a 'default' key.
    spec_dict = getattr(self, 'spec', {})
    for arg, arg_spec in spec_dict.items():
        # If the spec is a dict we look for 'default' or a callable that
        # produces a default (akin to a factory function). Fall back to the
        # value stored directly on the instance if it differs from None.
        if isinstance(arg_spec, dict):
            if 'default' in arg_spec:
                defaults[arg] = arg_spec['default']
            elif 'default_factory' in arg_spec and callable(arg_spec['default_factory']):
                defaults[arg] = arg_spec['default_factory']()
            else:
                # No explicit default; try to use an attribute on the instance.
                if hasattr(self, arg):
                    defaults[arg] = getattr(self, arg)
                else:
                    defaults[arg] = None
        else:
            # If the spec entry is not a dict, treat it as the default value.
            defaults[arg] = arg_spec

    # Override with existing instance attributes if they are non-None.
    for arg in list(defaults):
        if hasattr(self, arg):
            value = getattr(self, arg)
            if value is not None:
                defaults[arg] = value

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    # Retrieve the specification. The attribute name may vary,
    # so try common possibilities.
    spec = getattr(self, "_spec", None) or getattr(self, "spec", None) or {}
    if not isinstance(spec, dict):
        spec = {}

    # The spec may describe arguments in a few different ways:
    #  * a mapping of argument name -> default value,
    #  * a list of argument descriptors (each with 'name' and optional 'default'),
    #  * a nested mapping under a 'defaults' or 'args' key.
    defaults = {}

    # Check for a plain defaults mapping
    if "defaults" in spec and isinstance(spec["defaults"], dict):
        defaults.update(spec["defaults"])

    # Handle a list of argument descriptors
    if "args" in spec and isinstance(spec["args"], list):
        for item in spec["args"]:
            if isinstance(item, dict) and "name" in item:
                name = item["name"]
                if "default" in item:
                    defaults.setdefault(name, item["default"])

    # If the spec itself is a simple mapping of arg -> default
    if isinstance(spec, dict):
        for key, value in spec.items():
            if key not in ("defaults", "args", "env") and not callable(value):
                defaults.setdefault(key, value)

    # Resolve remaining values from other sources.
    # Priority: instance attribute > config dict > environment variable > None.
    for arg in list(defaults):
        if defaults[arg] is None:
            # instance attribute
            if hasattr(self, arg):
                defaults[arg] = getattr(self, arg)
            # config dictionary
            elif hasattr(self, "_config") and isinstance(self._config, dict):
                defaults[arg] = self._config.get(arg)
            # environment variable (use uppercase name)
            else:
                env_name = arg.upper()
                try:
                    import os
                    defaults[arg] = os.getenv(env_name)
                except Exception:
                    defaults[arg] = None

    # Ensure all spec arguments have a value (default to None if still missing)
    spec_args = list(defaults.keys())
    if isinstance(spec, dict) and "args" in spec and isinstance(spec["args"], list):
        for item in spec["args"]:
            if isinstance(item, str):
                spec_args.append(item)
    for arg in spec_args:
        defaults.setdefault(arg, None)

    return defaults

