def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Mapping of deprecated argument names to their modern replacements.
    deprecated_map = getattr(self, "deprecated_args", {})

    if not deprecated_map:
        return

    # Helper to print a warning for a deprecated argument.
    def warn_deprecated(source, arg, replacement):
        print(
            f"WARNING: {source} argument '{arg}' is deprecated. "
            f"Use '{replacement}' instead."
        )

    # Check CLI arguments.
    for arg in cli_args.keys():
        if arg in deprecated_map:
            warn_deprecated("CLI", arg, deprecated_map[arg])

    # Check answer‑file arguments.
    for arg in answer_file_args.keys():
        if arg in deprecated_map:
            warn_deprecated("Answer File", arg, deprecated_map[arg])

def get_parser_option_specs(self, command_name):
        """
        Gets all the options for the specified command.

        :param command_name: the command name (main, virsh, ospd, etc...)
        :return: the list of all command options
        """
        # Validate input
        if not isinstance(command_name, str):
            raise TypeError("command_name must be a string")

        # Retrieve the option specs dictionary; raise informative error if missing
        try:
            specs = self._option_specs[command_name]
        except KeyError as exc:
            raise KeyError(f"No parser option specs found for command '{command_name}'") from exc

        # Return a shallow copy so callers cannot mutate our internal list
        return list(specs)

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Ensure the commands registry exists
    if not hasattr(self, 'commands') or not isinstance(self.commands, dict):
        raise AttributeError("The object does not have a 'commands' dictionary attribute.")
    # Retrieve the command object
    cmd = self.commands.get(command_name)
    if cmd is None:
        raise KeyError(f"Command '{command_name}' not found.")
    # Try to fetch the option spec from common patterns
    if hasattr(cmd, 'options') and isinstance(cmd.options, dict):
        opt_spec = cmd.options.get(argument_name)
        if opt_spec is None:
            raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'.")
        return opt_spec
    if hasattr(cmd, 'get_option'):
        try:
            return cmd.get_option(argument_name)
        except Exception as exc:
            raise KeyError(f"Failed to get option '{argument_name}' for command '{command_name}': {exc}") from exc
    raise AttributeError(f"Command object for '{command_name}' does not provide a way to access options.")

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Retrieve the mapping of all command specs. Fallback to attributes that may hold the spec.
    command_specs = getattr(self, "command_specs", None) or getattr(self, "_spec", getattr(self, "spec", {}))
    # If no command name supplied, use the root spec; otherwise locate the requested command.
    if command_name is None:
        command_spec = command_specs
    else:
        if command_name not in command_specs:
            raise KeyError(f"Command '{command_name}' not found.")
        command_spec = command_specs[command_name]
    # Extract the options dictionary from the command spec.
    if isinstance(command_spec, dict):
        options = command_spec.get("options", {})
    else:
        options = getattr(command_spec, "options", {})
    # Return the requested option spec or raise an error if missing.
    if argument_name not in options:
        raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'.")
    return options[argument_name]

