    # Retrieve the command specification
    cmd_spec = getattr(self, "commands", {}).get(command_name)
    if cmd_spec is None:
        raise KeyError(f"Command '{command_name}' not found")

    # Retrieve the option specification from the command
    opt_spec = getattr(cmd_spec, "options", {}).get(argument_name)
    if opt_spec is None:
