        if isinstance(options, list):
            for opt in options:
                if opt.get('name') == argument_name:
                    return opt
        return None

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent_args = []
    for name, value in args.items():
        # Treat None or empty values as silent
        if value is None:
            silent_args.append(name)
        elif hasattr(value, "__len__") and len(value) == 0:
            silent_args.append(name)
    return silent_args

def get_silent_args(self, args):
    """
    Return a list of argument names considered 'silenced'. The method examines the
    provided args, which may be a mapping or an iterable of names. For mappings,
    boolean values set to False or values that are None are treated as
    silenced. For iterable types, names beginning with an underscore are
    treated as silenced, mirroring a common convention for private or
    suppressed arguments.
    """
    if args is None:
        return []

    silent = []

    # Handle mapping types (e.g., dict)
    if isinstance(args, dict):
        for key, value in args.items():
            if isinstance(value, bool) and not value:
                silent.append(key)
            elif value is None:
                silent.append(key)

    # Handle iterable types (list, tuple, set, etc.)
    else:
        for arg in args:
            if isinstance(arg, str):
                # Treat names that start with '_' as silenced
                if arg.startswith("_"):
                    silent.append(arg)

    return silent

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent_args = []
    if not args:
        return silent_args
    for name, value in args.items():
        if value is None:
            silent_args.append(name)
    return silent_args

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    required = getattr(self, "required_args", None)
    if not required:
        # No required arguments specified; nothing to validate
        return
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary representing argument names to values")
    missing = [name for name in required if name not in args]
    if missing:
        missing_names = ", ".join(missing)
        raise ValueError(f"Missing required argument(s): {missing_names}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    Return a list of option names that have a satisfied ``required_when`` condition.

    :param command_name: str, the name of the command.
    :param options_spec: list of option specification dictionaries.
    :param args: dict of parsed arguments (name -> value).
    :return: list of option names that become required by their ``required_when`` condition.
    """
    required = []

    for opt in options_spec:
        cond = opt.get("required_when")
        if cond is None:
            continue

        # Determine if condition is satisfied.
        satisfied = False

        # Callable condition.
        if callable(cond):
            try:
                satisfied = cond(args, command_name)
            except TypeError:
                # Some callables expect only args.
                try:
                    satisfied = cond(args)
                except Exception:
                    satisfied = False

        # String condition -> treat as key in args that must be truthy.
        elif isinstance(cond, str):
            if cond in args:
                val = args[cond]
                satisfied = bool(val)

        # Iterable of conditions -> any True satisfies.
        elif isinstance(cond, (list, tuple)):
            for sub in cond:
                if isinstance(sub, str):
                    if sub in args and bool(args[sub]):
                        satisfied = True
                        break
                elif callable(sub):
                    try:
                        if sub(args, command_name):
                            satisfied = True
                            break
                    except TypeError:
                        if sub(args):
                            satisfied = True
                            break

        # Dict mapping command names to conditions or default.
        elif isinstance(cond, dict):
            # Get condition for current command or default if specified.
            conditioned = None
            if command_name in cond:
                conditioned = cond[command_name]
            elif "default" in cond:
                conditioned = cond["default"]

            if conditioned is not None:
                if isinstance(conditioned, str):
                    if conditioned in args and bool(args[conditioned]):
                        satisfied = True
                elif isinstance(conditioned, bool):
                    satisfied = conditioned
                elif callable(conditioned):
                    try:
                        satisfied = conditioned(args, command_name)
                    except TypeError:
                        try:
                            satisfied = conditioned(args)
                        except Exception:
                            satisfied = False

        # If evaluated to True, add name.
        if satisfied:
            name = opt.get("name")
            if name:
                required.append(name)

    return required

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        cond_required = []
        for spec in options_spec:
            # Skip specs that do not define a conditional requirement
            if 'required_when' not in spec:
                continue

            condition = spec['required_when']
            want_append = False

            # If the condition is a callable, invoke it with the arguments
            if callable(condition):
                try:
                    want_append = bool(condition(args))
                except Exception:
                    # If the callable fails, treat as not matched
                    want_append = False

            # If the condition is a string expression, try to evaluate it safely
            elif isinstance(condition, str):
                try:
                    # Use args dict for variable lookup; disallow globals
                    want_append = bool(eval(condition, {}, dict(args)))
                except Exception:
                    want_append = False

            if want_append:
                # Use standard keys for option names if available
                name = spec.get('name') or spec.get('arg') or spec.get('key')
                if name:
                    cond_required.append(name)

        return cond_required

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    # Ensure we work with a dict of arguments for the current command
    if not isinstance(args, dict):
        return []

    required = []

    for opt in options_spec:
        if not isinstance(opt, dict):
            continue

        if 'required_when' not in opt:
            continue

        condition = opt['required_when']
        # Only handle dictionary based conditions for now
        if not isinstance(condition, dict):
            continue

        matched = True
        for cond_key, cond_val in condition.items():
            # Skip condition if key missing in args
            if cond_key not in args:
                matched = False
                break

            actual_val = args[cond_key]

            # cond_val of None means simply validate truthiness
            if cond_val is None:
                if not actual_val:
                    matched = False
                    break
            else:
                # Allow list/tuple of acceptable values
                if isinstance(cond_val, (list, tuple)):
                    if actual_val not in cond_val:
                        matched = False
                        break
                else:
                    if actual_val != cond_val:
                        matched = False
                        break

        if matched and 'name' in opt:
            required.append(opt['name'])

    return required

def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
        """
        # Iterate over each argument in the provided dictionary.
        for arg_name, arg_value in args.items():
            # Determine the maximum length for this argument.
            max_len = getattr(self, f"{arg_name}_max_length", None)
            if max_len is None:
                # If no length constraint is defined, skip this argument.
                continue

            # Ensure the value is a string before checking its length.
            if isinstance(arg_value, str):
                if len(arg_value) > max_len:
                    raise ValueError(
                        f"Argument '{arg_name}' is too long: "
                        f"maximum allowed is {max_len} characters."
                    )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict")
    # Assume self.max_lengths is a dict mapping argument names to maximum allowed lengths
    max_lengths = getattr(self, "max_lengths", {})
    for key, value in args.items():
        max_len = max_lengths.get(key)
        if max_len is None:
            continue
        try:
            length = len(str(value))
        except Exception:
            continue
        if length > max_len:
            raise ValueError(f"Argument '{key}' length {length} exceeds maximum of {max_len}")

def validate_length_args(self, args):
