def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
        """
        # Dict of maximum lengths for arguments, e.g. {'title': 100, 'description': 500}
        max_lengths = getattr(self, "max_lengths", {})

        for arg_name, value in args.items():
            if value is None:
                continue  # skip optional/empty arguments

            # Get the allowed maximum length for this argument, if defined
            max_len = max_lengths.get(arg_name)
            if max_len is None:
                continue  # no length restriction for this argument

            # Only enforce length for string-like values
            if isinstance(value, (str, bytes)):
                if len(value) > max_len:
                    raise ValueError(
                        f"Argument '{arg_name}' length ({len(value)}) exceeds maximum ({max_len})."
                    )
            # Optionally, enforce length for list-like sequences
            elif isinstance(value, (list, tuple, set)):
                if len(value) > max_len:
                    raise ValueError(
                        f"Argument '{arg_name}' sequence length ({len(value)}) exceeds maximum ({max_len})."
                    )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified."""

    # Subclasses can override `allowed_lengths` to specify per-argument limits.
    allowed_lengths = getattr(self, 'allowed_lengths', {})

    for key, value in args.items():
        # Get the maximum allowed length for this key, if any.
        max_len = allowed_lengths.get(key)
        if max_len is None:
