def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # the mapping of argument names to their allowed choices
    choices_map = getattr(self, "choices", {})
    for name, allowed in choices_map.items():
        if name not in args:
            continue
        value = args[name]
        # Handle iterable values (e.g., list/tuple/set)
        if isinstance(value, (list, tuple, set)):
            for v in value:
                if v not in allowed:
                    raise ValueError(
                        f"Invalid value '{v}' for argument '{name}'. Allowed choices: {allowed}"
                    )
        else:
            if value not in allowed:
                raise ValueError(
                    f"Invalid value '{value}' for argument '{name}'. Allowed choices: {allowed}"
                )

def validate_choices_args(self, args):
        """
        Ensure that the value(s) of arguments that have defined choice
        constraints are within the allowed set.  The class can provide a
        mapping of argument names to an iterable of valid values via the
        ``choice_args`` attribute.  ``args`` may be an ``argparse.Namespace``
        (usual from ``ArgumentParser.parse_args``) or a plain dictionary.
        If an argument value is not a member of its choice set a
        ``ValueError`` is raised.

        Parameters
        ----------
        args : argparse.Namespace or dict
            The parsed command‑line arguments or a dict of argument names
            to values.
        """
        # Get the mapping of name -> valid choices. It may be defined as
        # ``self.choice_args`` or ``self.choices``.
        choice_map = getattr(self, 'choice_args', None)
        if choice_map is None:
            choice_map = getattr(self, 'choices', {})

        if not isinstance(choice_map, dict):
            # If the attribute exists but is not a dict, we cannot validate.
            return

        # Helper to fetch value from ``args`` (supporting either dict or
        # Namespace).
        def _get_value(name):
            if isinstance(args, dict):
                return args.get(name)
            # Assume argparse.Namespace which supports attribute access
            return getattr(args, name, None)

        for name, valid_choices in choice_map.items():
            value = _get_value(name)
            if value is None:
                # Argument was not supplied: nothing to check.
                continue

            # If the value is an iterable (but not a string), check every
            # element against the choice set.
            try:
                is_iterable = not isinstance(value, (str, bytes)) and hasattr(value, '__iter__')
            except Exception:
                is_iterable = False

            if is_iterable and not isinstance(value, (set, frozenset)):
                # For lists or tuples: all elements must be valid.
                for sub in value:
                    if sub not in valid_choices:
                        raise ValueError(
                            f'Choice for argument "{name}" contains invalid element '
                            f'"{sub}". Expected one of {valid_choices}.'
                        )
            else:
                # Single value must be in the allowed choices.
                if value not in valid_choices:
                    raise ValueError(
                        f'Invalid value "{value}" for argument "{name}". '
                        f'Expected one of {valid_choices}.'
                    )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.

    """
    # Resolve arguments to a dictionary
    try:
        arg_items = args.items()
    except AttributeError:
        arg_items = vars(args).items()

    # Iterate over each argument and validate its value against the allowed choices
    for name, value in arg_items:
        # Retrieve the list of allowed choices for this argument
        choices = getattr(self, "choices", {}).get(name)
        if choices is None:
            continue

        # Handle multiple values (list/tuple/set) or single value
        if isinstance(value, (list, tuple, set)):
            for v in value:
                if v not in choices:
                    raise ValueError(f"Invalid choice '{v}' for argument '{name}'. "
                                     f"Valid choices are: {choices}")
        else:
            if value not in choices:
                raise ValueError(f"Invalid choice '{value}' for argument '{name}'. "
                                 f"Valid choices are: {choices}")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Ensure args is a dictionary (handle argparse.Namespace objects)
    if not isinstance(args, dict):
        try:
            args = vars(args)
        except Exception:
            raise TypeError("`args` must be a dict or argparse.Namespace")

    # The class is expected to define a `choices` mapping:
    #   {'arg_name': [allowed_values, ...], ...}
    if not hasattr(self, "choices"):
        raise AttributeError("The instance has no attribute 'choices'.")

    for arg_name, allowed in self.choices.items():
        if arg_name not in args:
            continue  # argument not supplied; skip validation

        value = args[arg_name]
        if value not in allowed:
            raise ValueError(
                f"Invalid choice for argument '{arg_name}': {value!r}. "
                f"Expected one of: {allowed}."
            )
    return True

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.
        :param args: The received arguments.
        """
        # If no choice constraints defined, nothing to validate
        if not hasattr(self, "_choices") or not self._choices:
            return

        for arg_name, arg_value in args.items():
            # Skip if argument has no defined choices
            if arg_name not in self._choices:
                continue

            valid_choices = self._choices[arg_name]
            # If the argument value is a list/tuple, ensure every item is valid
            if isinstance(arg_value, (list, tuple)):
                for item in arg_value:
                    if item not in valid_choices:
                        raise ParameterValidationError(
                            f"Argument '{arg_name}' contains invalid value '{item}'. "
                            f"Valid values are: {valid_choices}"
                        )
            else:
                if arg_value not in valid_choices:
                    raise ParameterValidationError(
                        f"Argument '{arg_name}' has invalid value '{arg_value}'. "
                        f"Valid values are: {valid_choices}"
                    )

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Extract optional global min/max limits
    min_val = args.get('min')
    max_val = args.get('max')

    # If no bounds are provided, nothing to validate
    if min_val is None or max_val is None:
        return

    # Validate each argument against the bounds, skipping the min/max keys themselves
    for name, value in args.items():
        if name in ('min', 'max'):
            continue
        try:
            if value < min_val or value > max_val:
                raise ValueError(
                    f"Argument '{name}' with value {value} is out of bounds "
                    f"({min_val} <= value <= {max_val})"
                )
        except TypeError as exc:
            # The value is not comparable to the bounds (e.g., a string)
            raise TypeError(
                f"Argument '{name}' with value {value} cannot be compared to bounds "
                f"({min_val} <= value <= {max_val})"
            ) from exc

def validate_min_max_args(self, args):
    """
    Check if the value of each argument is between its defined minimum and maximum.

    E.g. if an argument specification stored in ``self.arg_specs`` looks like:
      {
          'limit': {'min': 0, 'max': 10},
      }
    then ``args['limit']`` must be between 0 and 10 inclusive.

    Parameters
    ----------
    args : dict
        The received arguments (name -> value).

    Raises
    ------
    ValueError
        If any value is below its minimum or above its maximum.
    """
    # The specification for all arguments is expected to be stored in
    # ``self.arg_specs``. Each spec may contain ``min`` and/or ``max`` keys.
    arg_specs = getattr(self, 'arg_specs', {})
    for name, value in args.items():
        spec = arg_specs.get(name)
        if spec is None:
            continue  # No bounds defined for this argument
        # Retrieve optional bounds
        min_val = spec.get('min')
        max_val = spec.get('max')
        # Type safe comparison: only check numeric or comparable values.
        if min_val is not None:
            try:
                if value < min_val:
                    raise ValueError(
                        f"Argument '{name}' must be >= {min_val}, got {value}"
                    )
            except TypeError:
                raise TypeError(
                    f"Cannot compare value of argument '{name}' ({value!r}) with minimum {min_val!r}"
                )
        if max_val is not None:
            try:
                if value > max_val:
                    raise ValueError(
                        f"Argument '{name}' must be <= {max_val}, got {value}"
                    )
            except TypeError:
                raise TypeError(
                    f"Cannot compare value of argument '{name}' ({value!r}) with maximum {max_val!r}"
                )

def validate_min_max_args(self, args):
    """
    Check if the values of arguments are between the defined minimum and maximum values.
    Each entry in `args` is expected to be a dictionary containing at least the key
    'value' with the actual argument value, and optionally 'min' and 'max' keys specifying
    the allowed bounds. Raise a ValueError if any value is outside its bounds.
    """
    for arg_name, arg_data in args.items():
        # If the argument data is provided as a dictionary containing metadata
        if isinstance(arg_data, dict):
            # Retrieve the actual value and optional bounds
            value = arg_data.get('value')
            min_val = arg_data.get('min')
            max_val = arg_data.get('max')
            # Skip validation if no explicit value is supplied
            if value is None:
                continue
            # Validate numeric values only
            if not isinstance(value, (int, float)):
                raise ValueError(f"Argument '{arg_name}' has a non-numeric value: {value!r}")
            if min_val is not None and value < min_val:
                raise ValueError(
                    f"Argument '{arg_name}' has value {value} which is less than "
                    f"the allowed minimum of {min_val}"
                )
            if max_val is not None and value > max_val:
                raise ValueError(
                    f"Argument '{arg_name}' has value {value} which exceeds "
                    f"the allowed maximum of {max_val}"
                )
        # If the argument data is a raw value, use optional class attributes for bounds
        else:
            value = arg_data
            if not isinstance(value, (int, float)):
                continue  # Non-numeric values are not subject to min/max constraints
            min_val = getattr(self, 'minimum', None)
            max_val = getattr(self, 'maximum', None)
            if min_val is not None and value < min_val:
                raise ValueError(
                    f"Argument '{arg_name}' has value {value} which is less than "
                    f"the allowed minimum of {min_val}"
                )
            if max_val is not None and value > max_val:
                raise ValueError(
                    f"Argument '{arg_name}' has value {value} which exceeds "
                    f"the allowed maximum of {max_val}"
                )

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments as a dictionary mapping argument names to their values.
    :raises ValueError: If any argument value is outside its defined minimum or maximum bounds.
    """
    # Retrieve the mapping that defines min/max bounds for each argument.
    # It could be defined in various ways; try common attribute names.
    range_defs = getattr(self, "validation_config", {}).get("min_max", {})
    if not range_defs:
        range_defs = getattr(self, "param_min_max", {})
    if not range_defs:
        # Try a generic 'parameters' dict which may contain min/max info.
        range_defs = {
            name: {"min": spec.get("min"), "max": spec.get("max")}
            for name, spec in getattr(self, "parameters", {}).items()
            if "min" in spec or "max" in spec
        }

    for name, value in args.items():
        # Skip arguments with no defined min/max.
        if name not in range_defs:
            continue

        spec = range_defs[name]
        min_val = spec.get("min")
        max_val = spec.get("max")
        if min_val is None and max_val is None:
            continue

        # Try to interpret the value as a number; if it cannot be converted, skip the check.
        try:
            num_value = float(value)
        except Exception:
            continue

        if min_val is not None and num_value < float(min_val):
            raise ValueError(
                f"Argument '{name}' value {value} is less than the minimum allowed {min_val}."
            )
        if max_val is not None and num_value > float(max_val):
            raise ValueError(
                f"Argument '{name}' value {value} is greater than the maximum allowed {max_val}."
            )

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments into control and nested arguments.
    Control arguments are identified by a ``control_`` prefix.
    Custom arguments are identified by a ``custom_`` prefix.
    All remaining arguments are treated as nested arguments.
    Args can be a mapping or an iterable of key/value pairs.
    Returns a tuple of dictionaries: (control_args, nested_args)
    """
    # Use dicts to accumulate results
    control_args = {}
    nested_args = {}

    # Normalise ``args`` to a mapping of key -> value.
    # It might already be a dict, or a list of tuples, or any iterable
    # which yields a (key, value) pair.
    if isinstance(args, dict):
        items = args.items()
    else:
        try:
            items = list(args)
        except TypeError:
            # If args is a single value we cannot split
            raise ValueError("Argument ``args`` must be a mapping or iterable of key/value pairs")

    for key, value in items:
        if key.startswith("control_"):
            # Strip the prefix for a cleaner key name
            stripped_key = key[len("control_") :]
            control_args[stripped_key] = value
        elif key.startswith("custom_"):
            # Custom arguments are treated as nested in the final spec,
            # but we keep them separate for potential future use
            stripped_key = key[len("custom_") :]
            nested_args[stripped_key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    # If args is a list of tuples, convert to list of (key, value)
    if isinstance(args, dict):
        items = args.items()
    else:
        items = args
    for k, v in items:
        if isinstance(k, str) and k.startswith("control_"):
            control_args[k] = v
        else:
            nested_args[k] = v
    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not extra_vars:
        return vars_dict

    # If the caller passed a dict, just update directly
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
        return vars_dict

    # Prepare a new dictionary to hold parsed values
    new_vars = {}

    # Helper to attempt JSON parsing for values
    def _parse_value(val):
        try:
            import json
            return json.loads(val)
        except Exception:
            return val

    # Handle iterable types: list, tuple, set
    if isinstance(extra_vars, (list, tuple, set)):
        for item in extra_vars:
            # Items can be dict, tuple/list of length 2, or a string
            if isinstance(item, dict):
                new_vars.update(item)
            elif isinstance(item, (tuple, list)) and len(item) == 2:
                key, value = item
                new_vars[key] = _parse_value(str(value))
            elif isinstance(item, str):
                # Parse key=value strings, strip whitespace
                if '=' in item:
                    key, _, value = item.partition('=')
                    key = key.strip()
                    value = value.strip()
                    if key:
                        new_vars[key] = _parse_value(value)
            else:
                # Skip unsupported types
                continue
    else:
        # Fallback: try to cast to dict
        try:
            new_vars.update(dict(extra_vars))
        except Exception:
            pass

    vars_dict.update(new_vars)
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not extra_vars:
        return vars_dict

    # Import json locally to avoid requiring a top‑level import
    import json
    for ev in extra_vars:
        if isinstance(ev, dict):
            # Direct dict merging
            vars_dict.update(ev)
        elif isinstance(ev, str):
            ev = ev.strip()
            # Try to parse JSON object
            try:
                parsed = json.loads(ev)
                if isinstance(parsed, dict):
                    vars_dict.update(parsed)
                    continue
            except Exception:
                pass

            # Fallback to key=value format
            if '=' in ev:
                key, val = ev.split('=', 1)
                vars_dict[key] = val

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``.

    Parameters
    ----------
    vars_dict : dict
        Dictionary to merge extra-vars into. A shallow copy is returned.
    extra_vars : None | dict | list | str, optional
        Extra variables to merge. Can be:
        * a dictionary, in which case it is merged directly;
        * a list of strings in the form ``'key=value'`` or a JSON
          literal (e.g. ``'{"k":"v"}'``);
        * a single string in the same format as a list element.

    Returns
    -------
    dict
        A new dictionary containing all key/value pairs from
        ``vars_dict`` merged with the supplied ``extra_vars``.
    """
    # If nothing to merge, just return a copy of the original dictionary
    if not extra_vars:
        return vars_dict.copy()

    merged = vars_dict.copy()

    # Helper to merge a dict into the result
    def _update_from_dict(d):
        if isinstance(d, dict):
            merged.update(d)

    # Handle dictionary input directly
    if isinstance(extra_vars, dict):
        _update_from_dict(extra_vars)
    else:
        # Treat non-dict inputs as iterable of strings or single string
        # Normalise to a list
        items = [extra_vars] if isinstance(extra_vars, str) else extra_vars

        for item in items:
            # If the item is a dict, merge
            if isinstance(item, dict):
                _update_from_dict(item)
                continue

            # If the item is a string, attempt to parse key=value
            if isinstance(item, str):
                # Try JSON first: e.g. '{"key":"value"}'
                try:
                    parsed = json.loads(item)
                    if isinstance(parsed, dict):
                        _update_from_dict(parsed)
                        continue
                except Exception:
                    pass  # not JSON, fall back to key=value parsing

                if '=' in item:
                    key, value = item.split('=', 1)
                    # Attempt to interpret the value as JSON to allow numbers, lists, etc.
                    try:
                        parsed_val = json.loads(value)
                    except Exception:
                        parsed_val = value
                    merged[key] = parsed_val
                else:
                    # No '=', ignore or log a warning
                    # (keeping behavior tolerant)
                    continue

    return merged

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """

    # Build base command
    cmd = ['ansible-playbook', playbook_path]

    # Handle verbosity
    if verbose:
        if isinstance(verbose, int):
            cmd.append('-v' * verbose)
        else:
            cmd.append('-v')

    # Handle ansible_args
    if ansible_args:
        for flag, value in ansible_args.items():
            if not flag.startswith('--'):
                flag = '--' + flag
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
            elif value is not None:
                cmd.extend([flag, str(value)])
            else:
                # None or False value: skip flag
                continue

    # Handle extra_vars
    if extra_vars:
        kvs = []
        for k, v in extra_vars.items():
            if isinstance(v, bool):
                if v:
                    kvs.append(k)
            else:
                kvs.append(f"{k}={v}")
        if kvs:
            cmd.extend(['--extra-vars', ' '.join(kvs)])

    # Execute command
    proc = subprocess.run(cmd, capture_output=True, text=True)

    # Raise if non-zero exit code
    if proc.returncode != 0:
        raise subprocess.CalledProcessError(
            returncode=proc.returncode,
            cmd=' '.join(cmd),
            output=proc.stdout,
            stderr=proc.stderr
        )

    return proc.returncode, proc.stdout + proc.stderr

def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts string arguments to their appropriate native types.
        Works recursively for comma‑separated lists.

        :param parser_name: The command name (currently unused).
        :param values_dict: The dictionary of arguments as strings.
        """
        bool_vals = {'true': True, 'false': False}
        def _convert(val):
            if isinstance(val, str):
                s = val.strip()
                # boolean
                lower = s.lower()
                if lower in bool_vals:
                    return bool_vals[lower]
                # integer
                try:
                    return int(s)
                except Exception:
                    pass
                # float
                try:
                    return float(s)
                except Exception:
                    pass
                # list
                if ',' in s:
                    parts = [x.strip() for x in s.split(',')]
                    return [_convert(x) for x in parts]
            return val

        for key, value in values_dict.items():
            values_dict[key] = _convert(value)

        # Return is optional – the dict is modified in place
        return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        # Define types for known parser names
        arg_type_map = {
            'main': {
                'count': int,
                'enable': bool,
                'threshold': float,
            },
            'virsh': {
                'timeout': int,
                'quiet': bool,
                'debug': bool,
            },
            'ospd': {
                'timeout': int,
                'verbose': bool,
                'retries': int,
            },
        }

        def parse_bool(s):
            if isinstance(s, bool):
                return s
            if isinstance(s, str):
                lower = s.lower()
                if lower in ('true', '1', 'yes', 'y', 'on'):
                    return True
                if lower in ('false', '0', 'no', 'n', 'off'):
                    return False
            raise ValueError(f"Cannot convert {s!r} to bool")

        # First apply explicit type conversions based on parser_name
        conversions = arg_type_map.get(parser_name, {})
        for key, typ in conversions.items():
            if key in values_dict:
                try:
                    if typ is bool:
                        values_dict[key] = parse_bool(values_dict[key])
                    else:
                        values_dict[key] = typ(values_dict[key])
                except Exception:
                    # If conversion fails, leave original value unchanged
                    pass

        # Then apply generic inference for remaining values
        for key, val in values_dict.items():
            if isinstance(val, str):
                # Try to parse as bool if not already typed
                try:
                    values_dict[key] = parse_bool(val)
                    continue
                except Exception:
                    pass
                # Try to parse as int or float
                try:
                    if '.' in val:
                        values_dict[key] = float(val)
                    else:
                        values_dict[key] = int(val)
                except Exception:
                    # Leave as string if parsing fails
                    pass

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        # Define the expected types for each parser_name.  New parsers can extend
        # this mapping with their own argument definitions.
        type_map = {
            'main': {
                'verbose': bool,
                'threads': int,
                'timeout': float,
            },
            'virsh': {
                'memory': int,
                'cpu': int,
                'debug': bool,
                'name': str,
            },
            'ospd': {
                'output': str,
                'interval': int,
                'dry_run': bool,
            },
        }

        # Get the mapping for the current parser; fall back to an empty dict if
        # the parser is not known.
        mapping = type_map.get(parser_name, {})

        for key, target_type in mapping.items():
            if key not in values_dict:
                continue  # nothing to convert

            raw_value = values_dict[key]
            try:
                # Special handling for booleans to accept common string forms.
                if target_type is bool and isinstance(raw_value, str):
                    lowered = raw_value.lower()
                    values_dict[key] = lowered in ('true', '1', 'yes', 'on')
                else:
                    values_dict[key] = target_type(raw_value)
            except Exception:
                # If conversion fails we simply leave the value unchanged.  This
                # avoids breaking the command flow due to malformed input.
                pass

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os, json
    # Look for common spec filenames
    for fname in ("plugin.json", "plugin.yaml", "plugin.yml", "spec.json", "spec.yaml", "spec.yml"):
        spec_path = os.path.join(plugin_dir, fname)
        if os.path.isfile(spec_path):
            break
    else:
        return {}
    # Load spec (YAML if available, otherwise JSON)
    if spec_path.lower().endswith((".yaml", ".yml")):
        try:
            import yaml
            with open(spec_path, "r", encoding="utf-8") as f:
                spec = yaml.safe_load(f)
        except Exception:
            return {}
    else:
        with open(spec_path, "r", encoding="utf-8") as f:
            spec = json.load(f)
    # Flatten a nested dictionary
    flat = {}
    def _flatten(d, parent_key=""):
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                _flatten(v, new_key)
            else:
                flat[new_key] = v
    if isinstance(spec, dict):
        _flatten(spec)
    return flat

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Determine the spec file (JSON or YAML)
    spec_file = None
    for fname in ("plugin.json", "plugin.yaml", "plugin.yml"):
        candidate = os.path.join(plugin_dir, fname)
        if os.path.isfile(candidate):
            spec_file = candidate
            break

    if not spec_file:
        # No specification file found
        return {}

    # Load the spec file
    with open(spec_file, "r", encoding="utf-8") as f:
        if spec_file.endswith(".json"):
            try:
                data = json.load(f)
            except Exception:
                return {}
        else:
            try:
                data = yaml.safe_load(f)
            except Exception:
                return {}

    # Recursively flatten nested dictionaries
    def _flatten(d, parent_key=""):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key))
            else:
                items[new_key] = v
        return items

    return _flatten(data)

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import json
    import pathlib
    import os

    # Determine spec file: prefer JSON, fallback to YAML
    plugin_path = pathlib.Path(plugin_dir)
    spec_file = None
    for ext in ["json", "yaml", "yml"]:
        candidate = plugin_path / f"plugin.{ext}"
        if candidate.is_file():
            spec_file = candidate
            file_ext = ext
            break
    if spec_file is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    # Load spec
    if file_ext == "json":
        with spec_file.open() as f:
            spec = json.load(f)
    else:
        try:
            import yaml
        except ImportError as exc:
            raise RuntimeError(
                "YAML support is required to load plugin spec "
                f"but the 'yaml' package is not installed."
            ) from exc
        with spec_file.open() as f:
            spec = yaml.safe_load(f)

    # Helper to flatten nested dictionaries
    def _flatten(current, parent_keys=None, sep="."):
        if parent_keys is None:
            parent_keys = []
        items = {}
        for key, value in (current or {}).items():
            full_key = sep.join(parent_keys + [key]) if parent_keys else key
            if isinstance(value, dict):
                items.update(_flatten(value, parent_keys + [key], sep=sep))
            elif isinstance(value, list):
                # For lists we join elements or keep list as string
                try:
                    items[full_key] = ",".join(map(str, value))
                except TypeError:
                    items[full_key] = str(value)
            else:
                items[full_key] = value
        return items

    return _flatten(spec)

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    os_mod = __import__('os')
    json_mod = __import__('json')
    # Determine spec file (currently only JSON supported)
    spec_file = os_mod.path.join(plugin_dir, 'plugin.json')
    if not os_mod.path.isfile(spec_file):
        # Try an alternative name
        spec_file = os_mod.path.join(plugin_dir, 'spec.json')
        if not os_mod.path.isfile(spec_file):
            return {}
    try:
        with open(spec_file, 'r', encoding='utf-8') as f:
            data = json_mod.load(f)
    except Exception:
        # If JSON parsing fails, return empty dict
        return {}

    flat_dict = {}

    def _flatten(current, parent_key=''):
        if isinstance(current, dict):
            for k, v in current.items():
                new_key = f"{parent_key}.{k}" if parent_key else k
                _flatten(v, new_key)
        else:
            flat_dict[parent_key] = current

    _flatten(data)
    return flat_dict

