def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    from pathlib import Path
    root = Path(root).resolve()
    path = Path(path).resolve()
    try:
        rel_path = path.relative_to(root)
    except ValueError:
        raise ValueError(f"Path '{path}' is not under root '{root}'.")
    return str(rel_path)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not root:
        raise ValueError("root must be a non-empty string")
    norm_path = os.path.normpath(path)
    norm_root = os.path.normpath(root)
    if norm_path == norm_root:
        return ''
    # Ensure root ends with separator
    if not norm_root.endswith(os.sep):
        norm_root_sep = norm_root + os.sep
    else:
        norm_root_sep = norm_root
    if norm_path.startswith(norm_root_sep):
        rel_path = norm_path[len(norm_root_sep):]
        return rel_path
    else:
        raise ValueError(f"Path '{path}' does not start with root '{root}'")

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import pathlib
    p = pathlib.Path(path).absolute()
    r = pathlib.Path(root).absolute()
    try:
        rel = p.relative_to(r)
    except ValueError:
        raise ValueError(f"Path {path} does not start with root {root}") from None
    return '' if rel == pathlib.Path('.') else str(rel)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    from pathlib import Path

    p = Path(path).resolve(strict=False)
    r = Path(root).resolve(strict=False)

    try:
        rel = p.relative_to(r)
    except ValueError:
        raise ValueError(f"'{root}' is not a prefix of '{path}'")
    return str(rel)
